1	import type { SupabaseClient } from "@supabase/supabase-js";
2	import { allPages } from "@/lib/all-pages";
3	import { calendarDate } from "./calendar";
4	import { buildSourceCoverage, type loadSourceCoverageMetadata } from "./source-coverage";
5	
6	export type BalanceAccount = { id: string; name: string; currency_code: string; type?: string; archived_at?: string | null; version?: number };
7	export type BalanceSnapshot = { id?: string; account_id: string; amount_minor: string | number; currency_code: string; as_of: string; provenance: string;
8	  boundary_kind?: string; source_transaction_id?: string | null; covered_transactions?: CoveredTransaction[] | null;
9	  actor_id?: string | null; undone_at?: string | null; version?: number; created_at?: string };
10	export type BalanceTransaction = { id: string; account_id: string; amount_minor: string | number; currency_code: string; posted_on: string; status: string;
11	  posted_at?: string | null; source_transaction_ids?: string[]; version?: number; description?: string;
12	  kind?: string; review_reasons?: string[]; canonical_amount_minor?: string | number; pending_released_minor?: string };
13	export type CoveredTransaction = { id: string; version: number; amount_minor: string; currency_code: string; posted_on: string; posted_at: string | null };
14	
15	// A review records financial fields and canonical identity, never ingestion order.
16	export function coveredTransaction(row: BalanceTransaction): CoveredTransaction {
17	  return { id: row.id, version: row.version ?? 0, amount_minor: exactMinor(row.amount_minor).toString(),
18	    currency_code: row.currency_code, posted_on: row.posted_on, posted_at: row.posted_at ? new Date(row.posted_at).toISOString() : null };
19	}
20	export function balanceReviewRows(ledger: BalanceTransaction[], accountId: string, asOf: string, timeZone: string) {
21	  const today = calendarDate(asOf, timeZone);
22	  return ledger.filter(row => row.account_id === accountId && row.status === "posted" && exactMinor(row.amount_minor) !== 0n &&
23	    (row.posted_at ? calendarDate(row.posted_at, timeZone) === today && Date.parse(row.posted_at) <= Date.parse(asOf) : row.posted_on === today))
24	    .map(coveredTransaction).sort((a, b) => a.id.localeCompare(b.id));
25	}
26	
27	function boundaryEvidence(snapshot: BalanceSnapshot) {
28	  return JSON.stringify([snapshot.boundary_kind ?? "date_only", snapshot.source_transaction_id ?? null,
29	    [...(snapshot.covered_transactions ?? [])].map(row => coveredTransaction({ ...row, account_id: snapshot.account_id, status: "posted" })).sort((a, b) => a.id.localeCompare(b.id))]);
30	}
31	
32	function exactMinor(value: string | number): bigint {
33	  if (typeof value === "number" && !Number.isSafeInteger(value)) throw new Error("Unsafe numeric balance evidence");
34	  return BigInt(value);
35	}
36	
37	export function resolveBalances<T extends BalanceAccount>(accounts: T[], snapshots: BalanceSnapshot[], ledger: BalanceTransaction[], asOf = new Date().toISOString(), timeZone = "Europe/Berlin", sourceMetadata?: Awaited<ReturnType<typeof loadSourceCoverageMetadata>>,
38	  // Display-only views may settle same-moment conflicts (e.g. overlapping statement imports) with the most recently recorded balance.
39	  { preferLatestRecorded = false } = {}) {
40	  const today = calendarDate(asOf, timeZone);
41	  const resolved = accounts.map(account => {
42	    const candidates = snapshots.filter(snapshot => snapshot.account_id === account.id && !snapshot.undone_at && Number.isFinite(Date.parse(snapshot.as_of)) && Date.parse(snapshot.as_of) <= Date.parse(asOf))
43	      .sort((a, b) => Date.parse(b.as_of) - Date.parse(a.as_of) || (preferLatestRecorded ? Date.parse(b.created_at ?? "") - Date.parse(a.created_at ?? "") || 0 : 0));
44	    const snapshot = candidates[0];
45	    const balance = { amount_minor: null as string | null, snapshot_amount_minor: null as string | null,
46	      estimated_amount_minor: null as string | null, currency_code: account.currency_code,
47	      snapshot_currency_code: snapshot?.currency_code ?? null, as_of: snapshot?.as_of ?? null,
48	      evaluated_at: asOf, provenance: snapshot?.provenance ?? null, status: "missing" as "current" | "stale" | "ambiguous" | "missing",
49	      warnings: [] as string[], reconciled_rows: 0, unconfirmed_rows: 0, snapshot_valid: false };
50	    if (!snapshot) { balance.warnings.push("No dated balance at or before the evaluation time"); return { ...account, balance }; }
51	    try {
52	      const amount = exactMinor(snapshot.amount_minor);
53	      balance.snapshot_amount_minor = amount.toString();
54	      if (snapshot.currency_code !== account.currency_code) throw new Error("Snapshot currency differs from account currency");
55	      const ties = candidates.filter(item => Date.parse(item.as_of) === Date.parse(snapshot.as_of));
56	      if (ties.some(item => item.currency_code !== snapshot.currency_code || exactMinor(item.amount_minor) !== amount || boundaryEvidence(item) !== boundaryEvidence(snapshot))) {
57	        if (!preferLatestRecorded) throw new Error("Conflicting snapshots have no evidenced financial order");
58	        balance.warnings.push("Conflicting balances on the same date; using the most recently recorded one");
59	      }
60	      balance.snapshot_valid = true;
61	      const boundaryDate = calendarDate(snapshot.as_of, timeZone);
62	      // Balances entered for today record the moment they were observed; past-dated ones start at local midnight.
63	      const observedDuringDay = calendarDate(new Date(Date.parse(snapshot.as_of) - 1).toISOString(), timeZone) === boundaryDate;
64	      const covered = new Set<string>();
65	      if (snapshot.boundary_kind === "reviewed_activity") {
66	        if (!Array.isArray(snapshot.covered_transactions)) throw new Error("Reviewed activity evidence is missing");
67	        const rowsById = new Map(ledger.filter(row => row.account_id === account.id && row.status === "posted").map(row => [row.id, row]));
68	        for (const receipt of snapshot.covered_transactions) {
69	          const row = rowsById.get(receipt.id);
70	          if (covered.has(receipt.id) || !row || JSON.stringify(coveredTransaction(row)) !== JSON.stringify(coveredTransaction({ ...receipt, account_id: account.id, status: "posted" })) ||
71	              row.currency_code !== account.currency_code || (row.posted_at && Date.parse(row.posted_at) > Date.parse(snapshot.as_of)))
72	            throw new Error("Reviewed activity changed; review the booked balance again");
73	          covered.add(receipt.id);
74	        }
75	      }
76	      let estimate = amount;
77	      for (const row of ledger) {
78	        if (row.account_id !== account.id || row.status !== "posted" || covered.has(row.id)) continue;
79	        const postingDate = row.posted_at ? calendarDate(row.posted_at, timeZone) : row.posted_on;
80	        if (postingDate < boundaryDate || postingDate > today ||
81	            (row.posted_at && Date.parse(row.posted_at) > Date.parse(asOf))) continue;
82	        const delta = exactMinor(row.amount_minor);
83	        if (delta === 0n) continue;
84	        if (snapshot.boundary_kind === "reviewed_activity" && postingDate === boundaryDate) {
85	          if (!row.posted_at || Date.parse(row.posted_at) <= Date.parse(snapshot.as_of))
86	            throw new Error("Same-day activity was not covered by the booked balance review");
87	        } else if (row.posted_at && snapshot.boundary_kind === "after_transaction" && snapshot.source_transaction_id) {
88	          const postingTime = Date.parse(row.posted_at), boundaryTime = Date.parse(snapshot.as_of);
89	          if (postingTime < boundaryTime) continue;
90	          if (postingTime === boundaryTime) {
91	            if (row.source_transaction_ids?.includes(snapshot.source_transaction_id)) continue;
92	            throw new Error("Same-timestamp ledger has no evidenced order relative to the snapshot");
93	          }
94	        } else if (postingDate === boundaryDate && !(row.posted_at && observedDuringDay && Date.parse(row.posted_at) > Date.parse(snapshot.as_of))) {
95	          // A balance typed in today without confirming today's postings may or may not include them.
96	          if (boundaryDate === today && snapshot.actor_id && (snapshot.boundary_kind ?? "date_only") === "date_only") balance.unconfirmed_rows++;
97	          continue;
98	        }
99	        // A date-only balance is that day's closing balance, unless it was observed during the day: then later timed rows still move it.
100	        if (row.currency_code !== account.currency_code) throw new Error("Ledger currency differs from account currency");
101	        estimate += delta;
102	        balance.reconciled_rows++;
103	      }
104	      balance.estimated_amount_minor = estimate.toString();
105	      balance.status = boundaryDate === today ? "current" : "stale";
106	      if (balance.unconfirmed_rows) balance.warnings.push(`Not confirmed to include today's ${balance.unconfirmed_rows === 1 ? "posting" : `${balance.unconfirmed_rows} postings`}; confirm today's activity when you set the balance`);
107	      // Older balance plus recorded later activity is still the best known balance; status keeps it labelled.
108	      balance.amount_minor = estimate.toString();
109	    } catch (error) {
110	      balance.status = "ambiguous";
111	      balance.estimated_amount_minor = null;
112	      balance.warnings.push(error instanceof Error ? error.message : "Invalid balance evidence");
113	    }
114	    return { ...account, balance };
115	  });
116	  return resolved.map(account => ({ ...account, sourceCoverage: buildSourceCoverage({
117	    from: account.balance.as_of ? calendarDate(account.balance.as_of, timeZone) : "0001-01-01", to: today,
118	    accountId: account.id, currencyCode: account.currency_code, ledgerBasis: "balance_activity",
119	  }, ledger.map(row => ({ ...row, kind: row.kind ?? "ordinary" })), sourceMetadata?.imports, sourceMetadata?.sources) }));
120	}
121	
122	// Every reader gets complete, workspace-scoped evidence instead of a silently truncated first page.
123	export async function loadBalanceEvidence(db: SupabaseClient, workspaceId: string, asOf = new Date().toISOString()): Promise<{
124	  accounts: BalanceAccount[]; snapshots: BalanceSnapshot[]; ledger: BalanceTransaction[]; asOf: string;
125	}> {
126	  const rows = <T>(table: string, columns: string) =>
127	    allPages<T>((from, to, count) => db.from(table).select(columns, count ? { count } : undefined).eq("workspace_id", workspaceId).order("id").range(from, to));
128	  const [accounts, snapshots, ledger, fees, resolutions] = await Promise.all([
129	    rows<BalanceAccount>("accounts", "id, name, type, currency_code, archived_at, version"),
130	    rows<BalanceSnapshot>("balance_snapshots", "id, account_id, amount_minor::text, currency_code, as_of, provenance, boundary_kind, source_transaction_id, covered_transactions, actor_id, undone_at, version, created_at"),
131	    rows<BalanceTransaction & { transaction_sources?: { source_transaction_id: string }[] }>("transactions", "id, account_id, amount_minor::text, currency_code, posted_on, posted_at, status, version, description, kind, review_reasons, transaction_sources(source_transaction_id)"),
132	    rows<{ transaction_id: string; fee_minor: string; treatment: string; transaction_links: { undone_at: string | null } }>("transaction_link_fees", "id, transaction_id, fee_minor::text, treatment, transaction_links!inner(undone_at)"),
133	    rows<{ pending_transaction_id: string | null; released_minor: string; undone_at: string | null }>("pending_hold_resolutions", "id, pending_transaction_id, released_minor::text, undone_at"),
134	  ]);
135	  const released = new Map<string, bigint>();
136	  for (const resolution of resolutions) if (!resolution.undone_at && resolution.pending_transaction_id) {
137	    released.set(resolution.pending_transaction_id, (released.get(resolution.pending_transaction_id) ?? 0n) + exactMinor(resolution.released_minor));
138	  }
139	  const additionalFees = new Map<string, bigint>();
140	  for (const fee of fees) {
141	    if (fee.treatment !== "additional" || fee.transaction_links.undone_at !== null) continue;
142	    const amount = exactMinor(fee.fee_minor);
143	    if (amount <= 0n) throw new Error("Invalid verified additional fee");
144	    additionalFees.set(fee.transaction_id, (additionalFees.get(fee.transaction_id) ?? 0n) + amount);
145	  }
146	  return { accounts, snapshots, ledger: ledger.map(row => ({ ...row,
147	    pending_released_minor: (released.get(row.id) ?? 0n).toString(),
148	    canonical_amount_minor: row.amount_minor,
149	    // This is derived balance evidence; the source posting and its boundary identity remain unchanged.
150	    amount_minor: additionalFees.has(row.id) ? (exactMinor(row.amount_minor) - additionalFees.get(row.id)!).toString() : row.amount_minor,
151	    source_transaction_ids: row.transaction_sources?.map(source => source.source_transaction_id) ?? [] })), asOf };
152	}
