6	const accounts = [{ id: "cash", name: "Cash", currency_code: "EUR" }];
7	const snapshot = { id: "snapshot", account_id: "cash", amount_minor: "10000", currency_code: "EUR", as_of: "2026-09-28T12:00:00Z", provenance: "manual" };
8	const transaction = { id: "transaction", account_id: "cash", amount_minor: "-1250", currency_code: "EUR", posted_on: "2026-09-29", status: "posted" };
9	const now = "2026-10-01T12:00:00Z";
