11	it("loads active additional fees exactly once while retaining canonical source boundaries", async () => {
12	  const dated = { ...snapshot, as_of: "2026-10-01T08:00:00Z", boundary_kind: "after_transaction", source_transaction_id: "source" };
13	  const canonical = [
14	    { ...transaction, posted_at: dated.as_of, posted_on: "2026-10-01", transaction_sources: [{ source_transaction_id: "source" }] },
15	    { ...transaction, id: "later", posted_at: "2026-10-01T10:00:00Z", posted_on: "2026-10-01" },
16	  ];
17	  const tables: Record<string, unknown[]> = { accounts, balance_snapshots: [dated], transactions: canonical,
18	    transaction_link_fees: [
19	      { transaction_id: "transaction", fee_minor: "100", treatment: "additional", transaction_links: { undone_at: null } },
20	      { transaction_id: "later", fee_minor: "25", treatment: "additional", transaction_links: { undone_at: null } },
21	      { transaction_id: "later", fee_minor: "500", treatment: "included", transaction_links: { undone_at: null } },
22	      { transaction_id: "later", fee_minor: "500", treatment: "additional", transaction_links: { undone_at: "2026-10-01" } },
23	    ] };
24	  const from = (table: string) => {
25	    const query = { select: () => query, eq: () => query, order: () => query, range: async () => ({ data: tables[table], error: null }) };
26	    return query;
27	  };
28	  const evidence = await loadBalanceEvidence({ from } as unknown as SupabaseClient, "workspace", now);
29	  expect(evidence.ledger.map(row => row.amount_minor)).toEqual(["-1350", "-1275"]);
30	  expect(canonical[0].amount_minor).toBe("-1250");
31	  expect(evidence.ledger[0].source_transaction_ids).toEqual(["source"]);
32	  expect(resolveBalances(evidence.accounts, evidence.snapshots, evidence.ledger, now)[0].balance)
33	    .toMatchObject({ amount_minor: "8725", status: "current", reconciled_rows: 1 });
34	});
