36	describe("evidenced account balances", () => {
37	  it("reconciles same-day activity only across a preserved after-transaction boundary", () => {
38	    const dated = { ...snapshot, as_of: "2026-10-01T08:00:00Z", boundary_kind: "after_transaction", source_transaction_id: "source" };
39	    const included = { ...transaction, posted_on: "2026-10-01", posted_at: dated.as_of, source_transaction_ids: ["source"] };
40	    const later = { ...transaction, id: "later", posted_on: "2026-10-01", posted_at: "2026-10-01T10:00:00Z" };
41	    expect(resolveBalances(accounts, [dated], [included, later], now)[0].balance).toMatchObject({ amount_minor: "8750", reconciled_rows: 1, status: "current" });
42	    expect(resolveBalances(accounts, [dated], [included, { ...later, posted_at: dated.as_of }], now)[0].balance?.status).toBe("ambiguous");
43	  });
44	  it("flags a balance typed in today that was not confirmed to include today's postings", () => {
45	    const typed = { ...snapshot, as_of: "2026-10-01T11:00:00Z", boundary_kind: "date_only", actor_id: "user" };
46	    const earlier = { ...transaction, posted_on: "2026-10-01", posted_at: "2026-10-01T09:00:00Z" };
47	    expect(resolveBalances(accounts, [typed], [earlier], now)[0].balance).toMatchObject({ amount_minor: "10000", status: "current", unconfirmed_rows: 1,
48	      warnings: ["Not confirmed to include today's posting; confirm today's activity when you set the balance"] });
49	    expect(resolveBalances(accounts, [{ ...typed, actor_id: null }], [earlier], now)[0].balance).toMatchObject({ unconfirmed_rows: 0, warnings: [] });
50	    expect(resolveBalances(accounts, [typed], [], now)[0].balance).toMatchObject({ unconfirmed_rows: 0, warnings: [] });
51	  });
52	  it("labels old snapshots stale, uses them plus reconciled only later posted dates", () => {
53	    const [balance] = resolveBalances(accounts, [snapshot], [transaction,
54	      { ...transaction, id: "pending", status: "pending", amount_minor: "-500" },
55	      { ...transaction, id: "future", posted_on: "2026-10-02", amount_minor: "100000" }], now);
56	    expect(balance.balance).toMatchObject({ amount_minor: "8750", snapshot_amount_minor: "10000", estimated_amount_minor: "8750",
57	      as_of: snapshot.as_of, status: "stale", reconciled_rows: 1 });
58	  });
59	  it("excludes future snapshots and does not use ingestion order to resolve financial ties", () => {
60	    const tied = { ...snapshot, id: "tie", amount_minor: "11000", created_at: now };
61	    expect(resolveBalances(accounts, [snapshot, tied], [], now)[0].balance?.status).toBe("ambiguous");
62	    expect(resolveBalances(accounts, [tied, snapshot], [], now)[0].balance?.status).toBe("ambiguous");
63	    expect(resolveBalances(accounts, [{ ...snapshot, as_of: "2026-10-02T00:00:00Z" }], [], now)[0].balance?.status).toBe("missing");
64	  });
65	  it("lets display views settle same-moment ties with the most recently recorded balance", () => {
66	    const older = { ...snapshot, id: "older", created_at: "2026-09-30T10:00:00Z" }, newer = { ...snapshot, id: "newer", amount_minor: "11000", created_at: "2026-09-30T11:00:00Z" };
67	    for (const order of [[older, newer], [newer, older]]) expect(resolveBalances(accounts, order, [], now, undefined, undefined, { preferLatestRecorded: true })[0].balance)
68	      .toMatchObject({ amount_minor: "11000", snapshot_amount_minor: "11000", snapshot_valid: true, warnings: expect.arrayContaining([expect.stringContaining("most recently recorded")]) });
69	  });
70	  it("treats same-day date-only rows as included and refuses unsafe numeric database values", () => {
71	    const today = { ...snapshot, as_of: "2026-10-01T08:00:00Z" };
72	    expect(resolveBalances(accounts, [today], [], now)[0].balance?.amount_minor).toBe("10000");
73	    expect(resolveBalances(accounts, [today], [{ ...transaction, posted_on: "2026-10-01" }], now)[0].balance)
74	      .toMatchObject({ amount_minor: "10000", status: "current" });
75	    expect(resolveBalances(accounts, [{ ...today, amount_minor: Number.MAX_SAFE_INTEGER + 1 }], [], now)[0].balance)
76	      .toMatchObject({ amount_minor: null, status: "ambiguous" });
77	    expect(resolveBalances(accounts, [{ ...today, currency_code: "USD" }], [], now)[0].balance?.status).toBe("ambiguous");
78	  });
79	  it("counts same-day rows timed after a balance observed during that day", () => {
80	    const observed = { ...snapshot, as_of: "2026-10-01T08:00:00Z" };
81	    const spent = { ...transaction, posted_on: "2026-10-01", posted_at: "2026-10-01T09:00:00Z" };
82	    expect(resolveBalances(accounts, [observed], [spent], now)[0].balance?.amount_minor).toBe("8750");
83	    expect(resolveBalances(accounts, [observed], [{ ...spent, posted_at: "2026-10-01T07:00:00Z" }], now)[0].balance?.amount_minor).toBe("10000");
84	    // A balance dated to a past day starts at local midnight and stays that day's closing balance.
85	    const dated = { ...snapshot, as_of: calendarDayBoundary("2026-09-29", "Europe/Berlin") };
86	    expect(resolveBalances(accounts, [dated], [{ ...spent, posted_on: "2026-09-29", posted_at: "2026-09-29T09:00:00Z" }], now)[0].balance?.amount_minor).toBe("10000");
87	  });
88	});
