1	// Money is always signed integer minor units. Conversion must happen before calling.
2	export type Balance = { amountMinor: bigint | null; currencyCode: string };
3	
4	export function netWorth(balances: Balance[], currencyCode: string): bigint | null {
5	  if (balances.some(balance => balance.amountMinor === null || balance.currencyCode !== currencyCode)) return null;
6	  return balances.reduce((total, balance) => total + balance.amountMinor!, 0n);
7	}
8	
9	export type CashflowTransaction = {
10	  amountMinor: bigint;
11	  currencyCode: string;
12	  status: "posted" | "pending";
13	  kind: "ordinary" | "transfer" | "refund";
14	  reviewReasons?: string[];
15	};
16	
17	export function summarizeCashflow(transactions: CashflowTransaction[], currencyCode: string) {
18	  let incomeMinor = 0n;
19	  let spendingMinor = 0n;
20	  let excludedReviewRows = 0;
21	  for (const transaction of transactions) {
22	    if (transaction.status !== "posted") continue;
23	    if (transaction.reviewReasons?.length) { excludedReviewRows++; continue; }
24	    if (transaction.kind === "transfer") continue;
25	    if (transaction.currencyCode !== currencyCode) return null;
26	    if (transaction.kind === "refund") spendingMinor -= transaction.amountMinor;
27	    else if (transaction.amountMinor > 0n) incomeMinor += transaction.amountMinor;
28	    else spendingMinor -= transaction.amountMinor;
29	  }
30	  return { incomeMinor, spendingMinor, netMinor: incomeMinor - spendingMinor,
31	    ...(excludedReviewRows ? { excludedReviewRows, partial: true as const } : {}) };
32	}
33	
34	export type ForecastAccount = {
35	  id: string;
36	  currencyCode: string;
37	  balanceMinor: bigint | null;
38	  // A bank's available balance already includes pending holds. Use it instead of deducting holds again.
39	  availableMinor?: bigint | null;
40	  pendingHoldMinor?: bigint;
41	  reservedMinor?: bigint;
42	  safetyBufferMinor?: bigint;
