79	function parseDate(date: string): number {
80	  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new Error(`Invalid date: ${date}`);
81	  const timestamp = Date.parse(`${date}T00:00:00Z`);
82	  if (!Number.isFinite(timestamp) || new Date(timestamp).toISOString().slice(0, 10) !== date) throw new Error(`Invalid date: ${date}`);
83	  return timestamp;
84	}
85	
86	export function forecastDaily(input: ForecastInput): ForecastResult {
87	  const start = parseDate(input.startDate);
88	  if (!Number.isSafeInteger(input.horizonDays) || input.horizonDays < 1 || input.horizonDays > 3660) throw new Error("Invalid forecast horizon");
89	  const ids = new Set(input.accounts.map(account => account.id));
90	  if (ids.size !== input.accounts.length) throw new Error("Duplicate account ID");
91	  const events = [...input.events, ...(input.scenarioEvents ?? [])];
92	  for (const event of events) {
93	    parseDate(event.date);
94	    if (!ids.has(event.accountId)) throw new Error(`Unknown account: ${event.accountId}`);
95	  }
96	  const missingInputs = [...(input.missingInputs ?? [])];
97	  if (!input.accounts.length) missingInputs.push("accounts");
98	  for (const account of input.accounts) {
99	    if (account.currencyCode !== input.currencyCode) missingInputs.push(`fx:${account.id}`);
100	    if (account.availableMinor == null && account.balanceMinor === null) missingInputs.push(`balance:${account.id}`);
101	    if (account.availableMinor === null) missingInputs.push(`available-balance:${account.id}`);
102	  }
103	  if (missingInputs.length) return { status: "unavailable", missingInputs };
104	
105	  const balances = new Map<string, { expected: bigint; conservative: bigint; optimistic: bigint }>(input.accounts.map(account => {
106	    const initial = account.availableMinor ?? account.balanceMinor! - (account.pendingHoldMinor ?? 0n);
107	    return [account.id, { expected: initial, conservative: initial, optimistic: initial }];
108	  }));
109	  const days: ForecastDay[] = [];
110	  for (let offset = 0; offset < input.horizonDays; offset++) {
111	    const date = new Date(start + offset * 86400000).toISOString().slice(0, 10);
112	    for (const event of events) {
113	      if (event.date !== date) continue;
114	      const balance = balances.get(event.accountId)!;
115	      balance.expected += event.expectedMinor;
116	      balance.conservative += event.conservativeMinor ?? event.expectedMinor;
117	      balance.optimistic += event.optimisticMinor ?? event.expectedMinor;
118	    }
119	    const conservativeByAccount = Object.fromEntries([...balances].map(([id, balance]) => [id, balance.conservative]));
120	    days.push({
121	      date,
122	      expectedMinor: [...balances.values()].reduce((sum, balance) => sum + balance.expected, 0n),
123	      conservativeMinor: [...balances.values()].reduce((sum, balance) => sum + balance.conservative, 0n),
124	      optimisticMinor: [...balances.values()].reduce((sum, balance) => sum + balance.optimistic, 0n),
125	      conservativeByAccount,
126	    });
127	  }
128	  return { status: "available", days };
129	}
