131	export function availableToSpend(input: ForecastInput):
132	  | { status: "unavailable"; missingInputs: string[] }
133	  | { status: "available"; amountMinor: bigint; limitingDate: string } {
134	  const forecast = forecastDaily(input);
135	  if (forecast.status === "unavailable") return forecast;
136	  const protectedMinor = (input.workspaceBufferMinor ?? 0n) + input.accounts.reduce((sum, account) => sum + (account.reservedMinor ?? 0n) + (account.safetyBufferMinor ?? 0n) + (account.minimumMinor ?? 0n), 0n);
137	  const limitingDay = forecast.days.reduce((lowest, day) => day.conservativeMinor < lowest.conservativeMinor ? day : lowest);
138	  return { status: "available", amountMinor: limitingDay.conservativeMinor - protectedMinor, limitingDate: limitingDay.date };
139	}
