141	// These amounts are in input.currencyCode, after explicit dated FX conversion by the loader.
142	// Inputs that make one account's own cash unknown, as opposed to the plan's as a whole.
143	const ACCOUNT_INPUT = /^(?:balance|available-balance|fx:balance|fx:allocation|fx:pending|fx:assumption|fx:debt|debt|fx):([^:]+)/;
144	/** The account a missing input is about, when it names one. */
145	export const missingInputAccount = (key: string) => ACCOUNT_INPUT.exec(key)?.[1] ?? null;
146	
147	/**
148	 * The forecast limited to accounts whose cash is known, for a person who asked for an answer with its coverage stated.
149	 * A left-out account's balance and scheduled money are absent, so callers must show `excluded`. Gaps that are not
150	 * tied to one account (a schedule with no account, a missing spending account) still stop the forecast.
151	 */
152	export function usableForecastInput(input: ForecastInput) {
153	  const known = new Set(input.accounts.map(account => account.id));
154	  const named = (key: string) => { const id = ACCOUNT_INPUT.exec(key)?.[1]; return id && known.has(id) ? id : null; };
155	  const excluded = new Set(input.accounts.filter(account => account.availableMinor == null && account.balanceMinor === null).map(account => account.id));
156	  for (const key of input.missingInputs ?? []) { const id = named(key); if (id) excluded.add(id); }
157	  if (!excluded.size || excluded.size === input.accounts.length) return { input, excluded: [] as string[] };
158	  return { excluded: [...excluded], input: { ...input,
159	    accounts: input.accounts.filter(account => !excluded.has(account.id)),
160	    events: input.events.filter(event => !excluded.has(event.accountId)),
161	    scenarioEvents: input.scenarioEvents?.filter(event => !excluded.has(event.accountId)),
162	    missingInputs: (input.missingInputs ?? []).filter(key => !named(key)) } };
163	}
