165	export function accountLiquidity(input: ForecastInput) {
166	  const forecast = forecastDaily(input);
167	  if (forecast.status === "unavailable") return forecast;
168	  const aggregate = availableToSpend(input);
169	  if (aggregate.status === "unavailable") return aggregate;
170	  const accounts = input.accounts.map(account => {
171	    const protectedMinor = (account.reservedMinor ?? 0n) + (account.safetyBufferMinor ?? 0n) + (account.minimumMinor ?? 0n);
172	    const limitingDay = forecast.days.reduce((lowest, day) =>
173	      day.conservativeByAccount[account.id] < lowest.conservativeByAccount[account.id] ? day : lowest);
174	    const amountMinor = limitingDay.conservativeByAccount[account.id] - protectedMinor;
175	    const firstShortfallDate = forecast.days.find(day => day.conservativeByAccount[account.id] < protectedMinor)?.date ?? null;
176	    return { accountId: account.id, amountMinor, protectedMinor, limitingDate: limitingDay.date,
177	      spendableMinor: amountMinor < aggregate.amountMinor ? amountMinor : aggregate.amountMinor,
178	      spendingLimitingDate: amountMinor <= aggregate.amountMinor ? limitingDay.date : aggregate.limitingDate,
179	      shortfallMinor: amountMinor < 0n ? -amountMinor : 0n, firstShortfallDate,
180	      supportingEvents: [...input.events, ...(input.scenarioEvents ?? [])].filter(event =>
181	        event.accountId === account.id && event.date >= input.startDate && event.date <= limitingDay.date),
182	    };
183	  });
184	  const workspaceBufferMinor = input.workspaceBufferMinor ?? 0n;
185	  const beforeBuffer = aggregate.amountMinor + workspaceBufferMinor;
186	  const coveredBuffer = beforeBuffer > 0n ? beforeBuffer : 0n;
187	  const workspaceBufferPressureMinor = coveredBuffer < workspaceBufferMinor ? workspaceBufferMinor - coveredBuffer : 0n;
188	  return { status: "available" as const, currencyCode: input.currencyCode, aggregate, accounts, workspaceBufferMinor, workspaceBufferPressureMinor,
189	    hasShortfall: aggregate.amountMinor < 0n || accounts.some(account => account.shortfallMinor > 0n) };
190	}
