192	// Paired movements in the forecast currency; never an inferred cross-currency transfer.
193	export function internalFundingEvents(input: { date: string; fromAccountId: string; toAccountId: string; amountMinor: bigint }): ForecastEvent[] {
194	  parseDate(input.date);
195	  if (!input.fromAccountId || !input.toAccountId || input.fromAccountId === input.toAccountId || input.amountMinor <= 0n)
196	    throw new Error("Invalid internal funding");
197	  return [
198	    { date: input.date, accountId: input.fromAccountId, expectedMinor: -input.amountMinor, source: "scenario", name: "Internal funding out" },
199	    { date: input.date, accountId: input.toAccountId, expectedMinor: input.amountMinor, source: "scenario", name: "Internal funding in" },
200	  ];
201	}
202	
203	export function withInternalFunding(input: ForecastInput, funding: { date: string; currencyCode: string; fromAccountId: string; toAccountId: string; amountMinor: bigint }[]): ForecastInput {
204	  const end = parseDate(input.startDate) + input.horizonDays * 86400000;
205	  const events = funding.flatMap(item => {
206	    if (item.currencyCode !== input.currencyCode) throw new Error("Funding currency must match forecast currency; convert explicitly first");
207	    if (parseDate(item.date) < parseDate(input.startDate) || parseDate(item.date) >= end) throw new Error("Funding date outside forecast horizon");
208	    if (!input.accounts.some(account => account.id === item.fromAccountId) || !input.accounts.some(account => account.id === item.toAccountId)) throw new Error("Unknown funding account");
209	    return internalFundingEvents(item);
210	  });
211	  return { ...input, scenarioEvents: [...(input.scenarioEvents ?? []), ...events] };
212	}
213	
214	export function serializeAccountLiquidity(result: ReturnType<typeof accountLiquidity>) {
215	  if (result.status === "unavailable") return result;
216	  return { ...result, workspaceBufferMinor: result.workspaceBufferMinor.toString(), workspaceBufferPressureMinor: result.workspaceBufferPressureMinor.toString(), aggregate: { ...result.aggregate, amountMinor: result.aggregate.amountMinor.toString() },
217	    accounts: result.accounts.map(account => ({ ...account, amountMinor: account.amountMinor.toString(),
218	      spendableMinor: account.spendableMinor.toString(), protectedMinor: account.protectedMinor.toString(), shortfallMinor: account.shortfallMinor.toString(),
219	      supportingEvents: account.supportingEvents.map(event => ({ ...event, expectedMinor: event.expectedMinor.toString(),
220	        conservativeMinor: (event.conservativeMinor ?? event.expectedMinor).toString(),
221	        optimisticMinor: (event.optimisticMinor ?? event.expectedMinor).toString() })),
222	    })),
223	  };
224	}
