7	export function decimalRatio(value: string) {
8	  const match = /^(\d{1,24})(?:\.(\d{1,18}))?$/.exec(value.trim());
9	  if (!match) throw new Error("Use a nonnegative decimal with a dot and no grouping");
10	  return { numerator: BigInt(match[1] + (match[2] ?? "")), denominator: 10n ** BigInt(match[2]?.length ?? 0) };
11	}
12	function rounded(numerator: bigint, denominator: bigint) { return (numerator * 2n + denominator) / (denominator * 2n); }
13	
14	export function holdingValue(quantity: string, unitPrice: string, currency: string): bigint {
15	  const q = decimalRatio(quantity); const p = decimalRatio(unitPrice);
16	  if (q.numerator === 0n) throw new Error("Quantity must be positive");
17	  const value = rounded(q.numerator * p.numerator * 10n ** BigInt(minorDigits(currency)), q.denominator * p.denominator);
18	  if (value > 9223372036854775807n) throw new Error("Value exceeds supported integer range");
19	  return value;
20	}
21	export function wealthAmount(value: string, currency: string) {
22	  const negative = value.trim().startsWith("-");
23	  const ratio = decimalRatio(negative ? value.trim().slice(1) : value);
24	  const scale = 10n ** BigInt(minorDigits(currency));
25	  if (ratio.denominator > scale) throw new Error("Amount has too many decimal places for this currency");
26	  const amount = ratio.numerator * scale / ratio.denominator * (negative ? -1n : 1n);
27	  if (amount < -9223372036854775808n || amount > 9223372036854775807n) throw new Error("Amount exceeds supported integer range");
28	  return amount;
29	}
30	function dateValue(value: string) {
31	  const date = new Date(`${value}T00:00:00Z`);
32	  if (!/^\d{4}-\d{2}-\d{2}$/.test(value) || !Number.isFinite(date.getTime()) || date.toISOString().slice(0, 10) !== value) throw new Error("Invalid calendar date");
33	  return date;
34	}
35	export function debtPayments(input: { principalMinor: bigint; annualRate: string; monthlyPaymentMinor: bigint; nextPaymentOn: string }, start: string, days: number) {
36	  const rate = decimalRatio(input.annualRate);
37	  if (rate.numerator > 1000n * rate.denominator || input.principalMinor > 0n || input.monthlyPaymentMinor <= 0n || !Number.isInteger(days) || days < 1 || days > 365) throw new Error("Invalid debt assumptions");
38	  const first = dateValue(input.nextPaymentOn); const from = dateValue(start); const end = from.getTime() + days * 86400000;
39	  if (first < from) throw new Error("Update the outstanding principal and next payment date before forecasting");
40	  let outstanding = -input.principalMinor;
41	  const result: { date: string; paymentMinor: bigint; interestMinor: bigint; principalMinor: bigint; remainingMinor: bigint }[] = [];
42	  for (let month = 0; month < 13 && outstanding > 0n; month++) {
43	    const date = new Date(Date.UTC(first.getUTCFullYear(), first.getUTCMonth() + month, 1));
44	    const last = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 0)).getUTCDate();
45	    date.setUTCDate(Math.min(first.getUTCDate(), last));
46	    if (date.getTime() >= end) break;
47	    const interestMinor = rounded(outstanding * rate.numerator, rate.denominator * 1200n);
48	    const due = outstanding + interestMinor;
49	    const paymentMinor = due < input.monthlyPaymentMinor ? due : input.monthlyPaymentMinor;
50	    const principalMinor = paymentMinor - interestMinor;
51	    outstanding = due - paymentMinor;
52	    result.push({ date: date.toISOString().slice(0, 10), paymentMinor, interestMinor, principalMinor, remainingMinor: outstanding });
53	  }
54	  return result;
55	}
