57	export type WealthValue = { id: string; name: string; amount_minor: string; currency_code: string; as_of: string; linked_account_id: string | null };
58	/** A valuation is current when dated today, or for money lent to or owed to a person: that is a fixed
59	 * amount, not a market value, so it stays current from the day it changed hands until repaid. */
60	export const currentOn = (row: Pick<WealthValue, "name" | "as_of">, today: string) => row.as_of === today || (row.as_of < today && parseIouName(row.name) !== null);
61	/** Net worth counts the last known value of everything: an older value is flagged in `outdated`, never dropped,
62	 * so a late or failed sync can't change the total. Only a value dated in the future is left out. */
63	export function wealthEvidence(rows: WealthValue[], today: string) {
64	  dateValue(today);
65	  const included: { id: string; name: string; amountMinor: bigint; currencyCode: string; asOf: string; provenance: string }[] = [];
66	  const excludedLinked: string[] = []; const missingInputs: string[] = []; const outdated: { id: string; name: string; asOf: string }[] = [];
67	  for (const row of rows) {
68	    if (row.linked_account_id) { excludedLinked.push(row.id); continue; }
69	    dateValue(row.as_of);
70	    if (row.as_of > today) { missingInputs.push(`valuation:${row.id}:future`); continue; }
71	    if (typeof row.amount_minor !== "string" || !/^-?\d+$/.test(row.amount_minor)) throw new Error("Invalid wealth money");
72	    minorDigits(row.currency_code);
73	    included.push({ id: row.id, name: row.name, amountMinor: BigInt(row.amount_minor), currencyCode: row.currency_code, asOf: row.as_of, provenance: "manual valuation" });
74	    if (!currentOn(row, today)) outdated.push({ id: row.id, name: row.name, asOf: row.as_of });
75	  }
76	  return { included, excludedLinked, missingInputs, outdated,
77	    sourceCoverage: buildSourceCoverage({ from: today, to: today, recordBasis: "manual_wealth" }, []),
78	    manualRecords: { accepted: rows.length, included: included.length, excludedLinked: excludedLinked.length, excludedDated: rows.length - included.length - excludedLinked.length } };
79	}
