145	    if (item.payment_transaction_id && (!pending || BigInt(pending.pending_released_minor ?? "0") > 0n || pending.account_id !== account.id || pending.currency_code !== item.currency_code || pending.status !== "pending" || pending.posted_on !== item.next_payment_on || minor(pending.amount_minor) !== -BigInt(item.monthly_payment_minor!))) {
