58	export function buildReviewInvestigation(rows: ReviewTransaction[], period: { from: string; to: string }, categories: { id: string; name: string }[], merchants: { id: string; name: string }[]) {
59	  const first = Date.parse(`${period.from}T00:00:00Z`), last = Date.parse(`${period.to}T00:00:00Z`);
60	  if (!Number.isFinite(first) || !Number.isFinite(last) || first > last) throw new Error("Invalid review period");
61	  const days = Math.floor((last - first) / 86400000) + 1;
62	  const comparisonPeriod = { from: new Date(first - days * 86400000).toISOString().slice(0, 10), to: new Date(first - 86400000).toISOString().slice(0, 10) };
63	  const current = rows.filter(row => row.posted_on >= period.from && row.posted_on <= period.to);
64	  function groups(column: "category_id" | "merchant_id", names: { id: string; name: string }[]) {
65	    const labels = new Map(names.map(name => [name.id, name.name]));
66	    const result = new Map<string, { id: string | null; name: string; currency: string; current: bigint; previous: bigint; sources: Set<string> }>();
67	    for (const row of rows) {
68	      if (row.status !== "posted" || row.kind === "transfer" || row.review_reasons?.length || row.posted_on < comparisonPeriod.from || row.posted_on > period.to) continue;
69	      const amount = BigInt(row.amount_minor), spending = amount < 0n ? -amount : row.kind === "refund" ? -amount : 0n;
70	      if (spending === 0n) continue;
71	      const id = column === "category_id" && row.kind === "refund" && row.refund_of_id ? row.refund_category_id ?? null : row[column], key = JSON.stringify([id, row.currency_code]);
72	      const group = result.get(key) ?? { id, name: id ? labels.get(id) ?? "Unknown" : column === "category_id" ? "Uncategorized" : "Unknown merchant", currency: row.currency_code, current: 0n, previous: 0n, sources: new Set<string>() };
73	      if (row.posted_on >= period.from) { group.current += spending; if (group.sources.size < 5) group.sources.add(`/money/transactions?transaction=${row.parent_transaction_id ?? row.id}`); }
74	      else group.previous += spending;
75	      result.set(key, group);
76	    }
77	    return [...result.values()].sort((a, b) => a.current > b.current ? -1 : a.current < b.current ? 1 : a.name.localeCompare(b.name)).slice(0, 50)
78	      .map(group => ({ id: group.id, name: group.name, currency: group.currency, spendingMinor: group.current.toString(), previousSpendingMinor: group.previous.toString(), changeMinor: (group.current - group.previous).toString(), sourceLinks: [...group.sources] }));
79	  }
80	  return { comparisonPeriod, categories: groups("category_id", categories), merchants: groups("merchant_id", merchants),
81	    classificationReview: { excludedRows: current.filter(row => row.status === "posted" && row.review_reasons?.length).length, link: "/import" },
82	    limits: ["Equal-length calendar periods; incomplete imports can affect comparisons", "Unreviewed classifications, pending rows and internal transfers are excluded", "Group changes describe booked evidence, not causes; refunds follow their attributable category"] };
83	}
