85	export function buildReviewEvidence(accounts: Account[], snapshots: BalanceSnapshot[], transactions: Transaction[], from: string, to: string,
86	  balanceEvidence: { asOf: string; ledger: BalanceTransaction[]; timeZone?: string; sourceMetadata?: Awaited<ReturnType<typeof loadSourceCoverageMetadata>> } = { asOf: new Date().toISOString(), ledger: [] }) {
87	  const accountEvidence = resolveBalances(accounts, snapshots, balanceEvidence.ledger, balanceEvidence.asOf, balanceEvidence.timeZone, balanceEvidence.sourceMetadata).map(account => {
88	    const balance = account.balance;
89	    return { id: account.id, name: account.name, currencyCode: account.currency_code,
90	      balanceMinor: balance.amount_minor, snapshotBalanceMinor: balance.snapshot_amount_minor,
91	      snapshotCurrencyCode: balance.snapshot_currency_code,
92	      estimatedBalanceMinor: balance.estimated_amount_minor, balanceStatus: balance.status,
93	      balanceWarnings: balance.warnings, evaluatedAt: balance.evaluated_at,
94	      asOf: balance.as_of, provenance: balance.provenance, sourceCoverage: account.sourceCoverage };
95	  });
96	  const currencies = [...new Set([...accounts.map(account => account.currency_code), ...transactions.map(transaction => transaction.currency_code)])];
97	  const cashflow: Record<string, { incomeMinor: string; spendingMinor: string; netMinor: string; excludedReviewRows?: number; partial?: boolean }> = {};
98	  const worth: Record<string, string | null> = {};
99	  for (const currency of currencies) {
100	    const relevant = transactions.filter(transaction => transaction.currency_code === currency);
101	    if (relevant.length) {
102	      const totals = summarizeCashflow(relevant.map(transaction => ({ amountMinor: BigInt(transaction.amount_minor), currencyCode: currency,
103	        status: transaction.status as CashflowTransaction["status"], kind: transaction.kind as CashflowTransaction["kind"], reviewReasons: transaction.review_reasons })), currency)!;
104	      cashflow[currency] = { incomeMinor: totals.incomeMinor.toString(), spendingMinor: totals.spendingMinor.toString(), netMinor: totals.netMinor.toString(),
105	        ...(totals.excludedReviewRows ? { excludedReviewRows: totals.excludedReviewRows, partial: true } : {}) };
106	    }
107	    const inCurrency = accountEvidence.filter(account => account.currencyCode === currency);
108	    if (inCurrency.length) worth[currency] = netWorth(inCurrency.map(account => ({ amountMinor: account.balanceMinor === null ? null : BigInt(account.balanceMinor), currencyCode: currency })), currency)?.toString() ?? null;
109	  }
110	  return { period: { from, to }, accounts: accountEvidence, cashflow, netWorth: worth };
111	}
