14	type Scheduled = { account_id: string | null; amount_minor: string; currency_code: string; cadence: string; starts_on: string; ends_on: string | null; enabled?: boolean; source?: string; schedule_anchor_on?: string | null };
15	
16	export function expandSchedule(item: Scheduled, start: string, days: number, uncertaintyBps = 1000): ForecastEvent[] {
17	  if (item.enabled === false || !item.account_id) return [];
18	  // edit_assumption retains this anchor for non-schedule edits and replaces it
19	  // with the intentional start date when date/cadence actually changes.
20	  const anchor = item.schedule_anchor_on ?? item.starts_on;
21	  const first = new Date(`${anchor}T00:00:00Z`);
22	  const horizon = new Date(`${start}T00:00:00Z`);
23	  const end = new Date(horizon.getTime() + days * 86400000);
24	  const events: ForecastEvent[] = [];
25	  const elapsedDays = Math.max(0, Math.floor((horizon.getTime() - first.getTime()) / 86400000));
26	  let firstIndex = 0;
27	  if (item.cadence === "daily") firstIndex = elapsedDays;
28	  else if (item.cadence === "weekly" || item.cadence === "biweekly") firstIndex = Math.floor(elapsedDays / (item.cadence === "weekly" ? 7 : 14));
29	  else if (item.cadence === "monthly" || item.cadence === "quarterly") firstIndex = Math.max(0, Math.floor(((horizon.getUTCFullYear() - first.getUTCFullYear()) * 12 + horizon.getUTCMonth() - first.getUTCMonth()) / (item.cadence === "monthly" ? 1 : 3)) - 1);
30	  else if (item.cadence === "yearly") firstIndex = Math.max(0, horizon.getUTCFullYear() - first.getUTCFullYear() - 1);
31	  const startMonth = first.getUTCMonth();
32	  const startDate = first.getUTCDate();
33	  for (let n = firstIndex; n < firstIndex + days + 2; n++) {
34	    const date = new Date(first);
35	    if (item.cadence === "once" && n > 0) break;
36	    if (item.cadence === "daily") date.setUTCDate(first.getUTCDate() + n);
37	    else if (item.cadence === "weekly" || item.cadence === "biweekly") date.setUTCDate(first.getUTCDate() + (item.cadence === "weekly" ? 7 : 14) * n);
38	    else if (item.cadence === "monthly" || item.cadence === "quarterly") {
39	      date.setUTCDate(1);
40	      date.setUTCMonth(first.getUTCMonth() + (item.cadence === "monthly" ? 1 : 3) * n);
41	      const lastDay = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 0)).getUTCDate();
42	      date.setUTCDate(Math.min(startDate, lastDay));
43	    } else if (item.cadence === "yearly") {
44	      const targetYear = first.getUTCFullYear() + n;
45	      const lastDay = new Date(Date.UTC(targetYear, startMonth + 1, 0)).getUTCDate();
46	      date.setUTCFullYear(targetYear);
47	      date.setUTCMonth(startMonth);
48	      date.setUTCDate(Math.min(startDate, lastDay));
49	    } else if (item.cadence !== "once") throw new Error(`Unknown cadence: ${item.cadence}`);
50	    if (date >= end || (item.ends_on && date.toISOString().slice(0, 10) > item.ends_on)) break;
51	    if (date < horizon || date.toISOString().slice(0, 10) < item.starts_on) continue;
52	    const amount = BigInt(item.amount_minor);
53	    events.push({ date: date.toISOString().slice(0, 10), accountId: item.account_id,
54	      ...forecastCases(amount, uncertaintyBps) });
55	  }
56	  return events;
57	}
