64	export async function evaluatePlanForWorkspace(supabase: SupabaseClient, workspace: { id: string; display_currency: string; timezone: string }, horizonDays = 30, scenarioId?: string,
65	  evidence?: { balanceEvidence?: ReturnType<typeof loadBalanceEvidence>; wealth?: ReturnType<typeof loadWealthItems>; canReadImports?: boolean; sourceMetadata?: ReturnType<typeof loadSourceCoverageMetadata> }) {
66	  if (!Number.isInteger(horizonDays) || horizonDays < 1 || horizonDays > 365) throw new Error("Invalid forecast horizon");
67	  async function allRows<T>(query: { range(from: number, to: number): PromiseLike<{ data: T[] | null; error: unknown }> }) {
68	    const rows: T[] = [];
69	    for (let offset = 0; ; offset += 500) {
70	      const page = await query.range(offset, offset + 499);
71	      if (page.error) throw page.error;
72	      rows.push(...(page.data ?? []));
73	      if (!page.data || page.data.length < 500) return rows;
74	    }
75	  }
76	  const sourceMetadataPromise = evidence?.sourceMetadata ?? loadSourceCoverageMetadata(supabase, workspace.id, evidence?.canReadImports ?? true);
77	  const [balanceEvidence, wealth, preferencesResult,
78	    allocations, assumptions, rates, recurringSeries, settlements, sourceMetadata] = await Promise.all([
79	      evidence?.balanceEvidence ?? loadBalanceEvidence(supabase, workspace.id),
80	      evidence?.wealth ?? loadWealthItems(supabase, workspace.id),
81	      supabase.from("forecast_preferences").select("currency_code, safety_buffer_minor::text, daily_spending_minor::text, uncertainty_bps, spending_account_id, spending_starts_on, version").eq("workspace_id", workspace.id).maybeSingle(),
82	      allRows(supabase.from("goal_allocations").select("id, goal_id, account_id, amount_minor::text, version").eq("workspace_id", workspace.id).order("id")),
83	      allRows(supabase.from("financial_assumptions").select("id, name, source, account_id, amount_minor::text, currency_code, cadence, starts_on, schedule_anchor_on, recurring_evidence_eligible, ends_on, enabled, confirmed, version")
84	        .eq("workspace_id", workspace.id).eq("enabled", true).eq("confirmed", true).is("removed_at", null).order("id")),
85	      allRows(supabase.from("fx_rates").select("id, from_currency, to_currency, rate_text, rate_date, source, created_at")
86	        .eq("workspace_id", workspace.id).eq("to_currency", workspace.display_currency).order("id")),
87	      allRows(supabase.from("recurring_series").select("id, assumption_id, recurring_series_transactions(transaction_id)")
88	        .eq("workspace_id", workspace.id).in("status", ["confirmed", "dismissed"]).eq("evidence_invalidated", false).order("id")),
89	      allRows<OccurrenceSettlement>(supabase.from("recurring_occurrence_settlements")
90	        .select("id, assumption_id, scheduled_on, transaction_id, completes_occurrence, receipt, undone_at, version")
91	        .eq("workspace_id", workspace.id).order("id")),
92	      sourceMetadataPromise,
93	    ]);
94	  if (preferencesResult.error) throw preferencesResult.error;
95	  const preferences = preferencesResult.data ? forecastPreferencesSchema.parse(preferencesResult.data) : defaultForecastPreferences(workspace.display_currency);
96	  const preferencesVersion = preferencesResult.data?.version ?? 0;
97	  const conversions: { input: Parameters<typeof convertFx>[0]; requestedDate: string; selectedRate: unknown; result: ReturnType<typeof convertFx> }[] = [];
98	  const convert = (amount: bigint, from: string, date: string) => {
99	    const rate = (rates ?? []).filter(row => row.from_currency === from && row.rate_date <= date)
100	      .sort((a, b) => b.rate_date.localeCompare(a.rate_date))[0];
101	    const input = { amountMinor: amount, from, to: workspace.display_currency,
102	      rate: rate?.rate_text, source: rate?.source ?? "forecast", date: rate?.rate_date ?? date };
103	    const result = convertFx(input);
104	    conversions.push({ input, requestedDate: date, selectedRate: rate ?? null, result });
105	    return result.status === "available" ? result.converted.amountMinor : null;
106	  };
107	  const reserved = new Map<string, bigint>();
108	  for (const allocation of allocations ?? []) reserved.set(allocation.account_id, (reserved.get(allocation.account_id) ?? 0n) + BigInt(allocation.amount_minor));
109	  const spendable = resolveBalances(balanceEvidence.accounts, balanceEvidence.snapshots, balanceEvidence.ledger, balanceEvidence.asOf, workspace.timezone, sourceMetadata)
110	    .filter(account => !account.archived_at && ["checking", "savings", "cash", "wallet"].includes(account.type ?? ""));
111	  const startDate = calendarDate(balanceEvidence.asOf, workspace.timezone);
112	  const accountIds = new Set(spendable.map(account => account.id));
113	  const missingInputs = (assumptions ?? []).flatMap(item =>
114	    !item.account_id || !accountIds.has(item.account_id) ? [`assumption account`] :
115	      []);
116	  const debts = buildDebtForecast(wealth, balanceEvidence.accounts, balanceEvidence.ledger, assumptions ?? [], startDate, horizonDays);
117	  missingInputs.push(...debts.missingInputs);
118	  const events: ForecastEvent[] = (assumptions ?? []).filter(item => item.account_id && accountIds.has(item.account_id) && !debts.excludedAssumptionIds.includes(item.id)).flatMap(item => {
119	    const planned = expandSchedule(item, startDate, horizonDays, preferences.uncertainty_bps);
120	    // Retain overdue explicit occurrences, including those reopened by undo or changed evidence.
121	    for (const date of new Set(settlements.filter(link => link.assumption_id === item.id && link.scheduled_on < startDate).map(link => link.scheduled_on))) {
122	      const past = expandSchedule(item, date, 1, preferences.uncertainty_bps);
123	      if (past[0]?.date === date) planned.push(past[0]);
124	    }
125	    return planned.flatMap(event => {
126	      const explicit = settlements.filter(link => link.assumption_id === item.id && link.scheduled_on === event.date);
127	      // Candidate dismissal and association Undo retain independent fulfillment proof
128	      // for an eligible user schedule; source corrections still invalidate it.
129	      if (!explicit.some(link => !link.undone_at) && (item.source === "recurring_confirmed" || item.recurring_evidence_eligible === true) && recurringSeries.some(series =>
130	        series.assumption_id === item.id && series.recurring_series_transactions.some((link: { transaction_id: string }) =>
131	          balanceEvidence.ledger.some(row => row.id === link.transaction_id && row.account_id === item.account_id &&
