134	            (!row.posted_at || Date.parse(row.posted_at) <= Date.parse(balanceEvidence.asOf)))))) return [];
135	      for (const link of explicit) if (!link.undone_at && !settlementPosting(item, link, balanceEvidence.ledger))
136	        missingInputs.push(`occurrence:${item.name}:${event.date}:${link.id}:evidence changed; undo or review the association`);
137	      if (explicit.length) return reconcileOccurrence(item, event.date, explicit, balanceEvidence.ledger, balanceEvidence.asOf, startDate, workspace.timezone).flatMap(movement => {
138	        const horizonEnd = new Date(`${startDate}T00:00:00Z`).getTime() + horizonDays * 86400000;
139	        if (Date.parse(`${movement.date}T00:00:00Z`) >= horizonEnd) return [];
140	        const cases = forecastCases(movement.amountMinor, movement.observed ? 0 : preferences.uncertainty_bps);
141	        const expectedMinor = convert(cases.expectedMinor, item.currency_code, movement.date);
142	        const conservativeMinor = convert(cases.conservativeMinor!, item.currency_code, movement.date);
143	        const optimisticMinor = convert(cases.optimisticMinor!, item.currency_code, movement.date);
144	        if (expectedMinor === null || conservativeMinor === null || optimisticMinor === null) { missingInputs.push(`fx:assumption:${item.account_id}`); return []; }
145	        return [{ ...event, date: movement.date, expectedMinor, conservativeMinor, optimisticMinor, source: "confirmed" as const, name: item.name }];
146	      });
147	      const cv = (amount: bigint) => convert(amount, item.currency_code, event.date);
148	      const expectedMinor = cv(event.expectedMinor), conservativeMinor = cv(event.conservativeMinor!), optimisticMinor = cv(event.optimisticMinor!);
149	      if (expectedMinor === null || conservativeMinor === null || optimisticMinor === null) { missingInputs.push(`fx:assumption:${item.account_id}`); return []; }
150	      return [{ ...event, expectedMinor, conservativeMinor, optimisticMinor, source: "confirmed" as const, name: item.name }];
151	    });
152	  });
153	  for (const repayment of debts.events) {
154	    const amount = convert(repayment.amountMinor, repayment.currencyCode, repayment.date);
155	    if (amount === null) { missingInputs.push(`fx:debt:${repayment.accountId}`); continue; }
156	    if (events.some(event => event.accountId === repayment.accountId && event.date === repayment.date && event.expectedMinor === amount)) {
