158	    }
159	    events.push({ date: repayment.date, accountId: repayment.accountId, expectedMinor: amount, conservativeMinor: amount, optimisticMinor: amount, source: "debt", name: "Debt repayment" });
160	  }
161	  if (BigInt(preferences.daily_spending_minor) > 0n) {
162	    if (!preferences.spending_account_id || !accountIds.has(preferences.spending_account_id)) missingInputs.push("estimated spending account");
163	    else for (const event of expandSchedule({ account_id: preferences.spending_account_id, currency_code: preferences.currency_code, amount_minor: (-BigInt(preferences.daily_spending_minor)).toString(), cadence: "daily", starts_on: preferences.spending_starts_on!, ends_on: null }, startDate, horizonDays, preferences.uncertainty_bps)) {
164	      const expectedMinor = convert(event.expectedMinor, preferences.currency_code, event.date);
165	      const conservativeMinor = convert(event.conservativeMinor!, preferences.currency_code, event.date);
166	      const optimisticMinor = convert(event.optimisticMinor!, preferences.currency_code, event.date);
167	      if (expectedMinor === null || conservativeMinor === null || optimisticMinor === null) missingInputs.push("fx:estimated spending");
168	      else events.push({ ...event, expectedMinor, conservativeMinor, optimisticMinor, source: "estimated", name: "Additional variable spending" });
169	    }
170	  }
171	  const safetyBufferMinor = BigInt(preferences.safety_buffer_minor) === 0n ? 0n : convert(BigInt(preferences.safety_buffer_minor), preferences.currency_code, startDate);
172	  if (safetyBufferMinor === null) missingInputs.push("fx:safety buffer");
173	  let scenarioEvents: ForecastEvent[] = [];
174	  let scenarioEvidence: unknown = null;
175	  if (scenarioId) {
176	    const { data: scenario } = await supabase.from("scenarios").select("id, version").eq("workspace_id", workspace.id).eq("id", scenarioId).is("removed_at", null).maybeSingle();
177	    if (!scenario) throw new Error("Scenario not found");
178	    const overrides = await allRows(supabase.from("scenario_overrides")
179	      .select("id, name, account_id, amount_delta_minor::text, currency_code, cadence, starts_on, ends_on, version")
180	      .eq("workspace_id", workspace.id).eq("scenario_id", scenarioId).is("removed_at", null).order("id"));
181	    scenarioEvidence = { scenario, overrides };
182	    missingInputs.push(...(overrides ?? []).flatMap(item => !item.account_id || !accountIds.has(item.account_id) ? ["scenario account"] : []));
183	    scenarioEvents = (overrides ?? []).flatMap(item => item.account_id && accountIds.has(item.account_id)
184	      ? expandSchedule({ ...item, amount_minor: item.amount_delta_minor }, startDate, horizonDays, preferences.uncertainty_bps).flatMap(event => {
185	        const cv = (amount: bigint) => convert(amount, item.currency_code, event.date);
186	        const expectedMinor = cv(event.expectedMinor), conservativeMinor = cv(event.conservativeMinor!), optimisticMinor = cv(event.optimisticMinor!);
187	        if (expectedMinor === null || conservativeMinor === null || optimisticMinor === null) { missingInputs.push(`fx:scenario:${item.id}`); return []; }
188	        return [{ ...event, expectedMinor, conservativeMinor, optimisticMinor, source: "scenario" as const, name: item.name }];
189	      }) : []);
190	  }
191	  const input: ForecastInput = {
192	    startDate, horizonDays, currencyCode: workspace.display_currency,
193	    workspaceBufferMinor: safetyBufferMinor ?? 0n,
194	    accounts: spendable.map(account => {
195	      const snapshot = account.balance;
196	      const balanceMinor = snapshot.amount_minor !== null ? convert(BigInt(snapshot.amount_minor), snapshot.currency_code, startDate) : null;
197	      const reservedMinor = convert(reserved.get(account.id) ?? 0n, account.currency_code, startDate);
198	      if (snapshot.amount_minor === null) missingInputs.push(`balance:${account.id}:${snapshot.status}`);
199	      else if (balanceMinor === null) missingInputs.push(`fx:balance:${account.id}`);
200	      if (reservedMinor === null) missingInputs.push(`fx:allocation:${account.id}`);
201	      let pendingHoldMinor = 0n;
202	      for (const row of balanceEvidence.ledger) {
203	        if (row.account_id !== account.id || row.status !== "pending" || row.posted_on > startDate || BigInt(row.amount_minor) >= 0n) continue;
204	        const outstanding = -BigInt(row.amount_minor) - BigInt(row.pending_released_minor ?? "0");
205	        if (outstanding < 0n) throw new Error("Pending releases exceed the recorded hold");
206	        const hold = convert(outstanding, row.currency_code, startDate);
207	        if (hold === null) missingInputs.push(`fx:pending:${account.id}`);
208	        else pendingHoldMinor += hold;
209	      }
210	      return { id: account.id, currencyCode: workspace.display_currency, balanceMinor,
211	        pendingHoldMinor,
212	        reservedMinor: reservedMinor ?? 0n };
213	    }),
214	    events, scenarioEvents, missingInputs,
215	  };
216	  const forecast = forecastDaily(input);
217	  const available = availableToSpend(input);
218	  const boundary = spendable.some(account => !account.balance.as_of) ? undefined : spendable.flatMap(account => account.balance.as_of ? [calendarDate(account.balance.as_of, workspace.timezone)] : []).sort()[0];
219	  const coverageEnd = new Date(Date.parse(`${startDate}T00:00:00Z`) + horizonDays * 86400000).toISOString().slice(0, 10);
220	  const sourceCoverage = buildSourceCoverage({ from: boundary ?? "0001-01-01", to: coverageEnd, accountIds: [...accountIds], ledgerBasis: "balance_activity" },
221	    balanceEvidence.ledger.filter(row => accountIds.has(row.account_id)).map(row => ({ ...row, kind: row.kind ?? "ordinary" })), sourceMetadata?.imports, sourceMetadata?.sources);
222	  // Preserve pre-conversion facts and revisions even when a changed rate rounds to the same minor unit.
223	  const calculationEvidence = { workspace: { displayCurrency: workspace.display_currency, timezone: workspace.timezone }, startDate,
224	    balances: { accounts: balanceEvidence.accounts, snapshots: balanceEvidence.snapshots, ledger: balanceEvidence.ledger },
225	    wealth, debts, preferences, preferencesVersion, allocations, assumptions, rates, recurringSeries, settlements, sourceMetadata, scenario: scenarioEvidence, conversions };
226	  return { forecast, available, liquidity: accountLiquidity(input), input, preferences, preferencesVersion, sourceCoverage,
227	    calculationEvidence, sourceVersion: evidenceFingerprint(calculationEvidence),
228	    accountLabels: spendable.map(account => ({ id: account.id, name: account.name })),
229	    resultBasis: "accepted balance evidence and confirmed assumptions; source completeness unknown" };
230	}
