13	// Month ends for the last `months` months, then today.
14	export function monthEnds(today: string, months: number): string[] {
15	  const [year, month] = today.split("-").map(Number);
16	  const dates = Array.from({ length: months }, (_, index) => new Date(Date.UTC(year, month - 1 - (months - 1 - index), 0)).toISOString().slice(0, 10));
17	  return [...dates, today];
18	}
