20	// Every calendar day from `from` to `to`, inclusive.
21	export function dayRange(from: string, to: string): string[] {
22	  const dates: string[] = [];
23	  for (let time = Date.parse(`${from}T00:00:00Z`), end = Date.parse(`${to}T00:00:00Z`); time <= end; time += 86400000) dates.push(new Date(time).toISOString().slice(0, 10));
24	  return dates;
25	}
