27	// Recorded net worth on each date: the latest recorded account balance plus the posted transactions after
28	// its day, and the latest standalone valuation dated on or before it. No FX and no interpolation.
29	// With a ledger, a date before an account's first recorded balance is worked back from that balance by
30	// removing the posted transactions after the date, but only from the day before its first posting, since
31	// earlier activity is not on record. `known` is false when nothing covers the date.
32	// Today's point should come from `currentNetWorth`, which uses the exact resolved balances every screen shows.
33	// `calculated` adds Scalable's worked-out value to dates before its first real synced value, never on or after it, so
34	// nothing counts twice. It only joins a date something else already covers: alone, it would draw portfolio-only
35	// numbers and then a false jump up when bank data starts.
36	// ponytail: archived accounts are left out (matching Home); include them if history must show closed accounts.
37	export function netWorthSeries({ dates, timeZone, accountIds, snapshots, valuations, removedOn, ledger = [], calculated }: {
38	  dates: string[]; timeZone: string; accountIds: Set<string>; snapshots: Snapshot[]; valuations: Valuation[]; removedOn: Map<string, string>; ledger?: Posting[];
39	  calculated?: { rows: CalculatedValue[]; before: string | null };
40	}): NetWorthPoint[] {
41	  const calculatedOn = new Map((calculated?.rows ?? []).map(row => [row.on_date, row]));
42	  const balances = snapshots.filter(row => !row.undone_at && accountIds.has(row.account_id))
43	    .map(row => ({ key: row.account_id, date: calendarDate(row.as_of, timeZone), at: row.as_of, amount: BigInt(row.amount_minor), currency: row.currency_code,
44	      // As in resolveBalances: a balance typed in during the day is moved by later timed postings that day; a dated one is that day's closing balance.
45	      observed: calendarDate(new Date(Date.parse(row.as_of) - 1).toISOString(), timeZone) === calendarDate(row.as_of, timeZone) }));
46	  const values = valuations.filter(row => !row.linked_account_id)
47	    .map(row => ({ key: row.item_id, date: row.as_of, at: row.created_at, amount: BigInt(row.amount_minor), currency: row.currency_code, debt: row.kind === "debt" }));
48	  const latest = <T extends { key: string; date: string; at: string }>(rows: T[], date: string) => {
49	    const pick = new Map<string, T>();
50	    for (const row of rows) {
51	      if (row.date > date) continue;
52	      const prior = pick.get(row.key);
53	      if (!prior || row.date > prior.date || (row.date === prior.date && row.at >= prior.at)) pick.set(row.key, row);
54	    }
55	    return pick.values();
56	  };
57	  const posted = ledger.filter(row => row.status === "posted" && accountIds.has(row.account_id))
58	    .map(row => ({ ...row, day: row.posted_at ? calendarDate(row.posted_at, timeZone) : row.posted_on, amount: BigInt(row.amount_minor) }));
59	  const afterBalance = (row: typeof posted[number], balance: typeof balances[number]) => row.day > balance.date ||
60	    (row.day === balance.date && balance.observed && !!row.posted_at && Date.parse(row.posted_at) > Date.parse(balance.at));
61	  const sum = (rows: typeof posted) => rows.reduce((total, row) => total + row.amount, 0n);
62	  const firstPosted = new Map<string, string>();
63	  for (const row of posted) if (!firstPosted.has(row.account_id) || row.posted_on < firstPosted.get(row.account_id)!) firstPosted.set(row.account_id, row.posted_on);
64	  const dayBefore = (date: string) => new Date(Date.parse(`${date}T00:00:00Z`) - 86400000).toISOString().slice(0, 10);
65	  return dates.map(date => {
66	    const point: NetWorthPoint = { date, accounts: new Map(), assets: new Map(), debts: new Map(), known: false };
67	    const recorded = [...latest(balances, date)];
68	    for (const row of recorded) add(point.accounts, row.currency, row.amount + sum(posted.filter(item => item.account_id === row.key && item.currency_code === row.currency && afterBalance(item, row) && item.day <= date)));
69	    for (const key of accountIds) {
70	      const first = firstPosted.get(key);
71	      if (recorded.some(row => row.key === key) || !first || date < dayBefore(first)) continue;
72	      const next = balances.filter(row => row.key === key && row.date > date).sort((a, b) => a.date.localeCompare(b.date) || a.at.localeCompare(b.at))[0];
73	      if (!next) continue;
74	      add(point.accounts, next.currency, next.amount - sum(posted.filter(row => row.account_id === key && row.currency_code === next.currency && row.day > date && !afterBalance(row, next))));
75	    }
76	    for (const row of latest(values, date)) {
77	      const removed = removedOn.get(row.key);
78	      if (removed && removed <= date) continue;
79	      add(row.debt ? point.debts : point.assets, row.currency, row.amount);
80	    }
81	    point.known = point.accounts.size + point.assets.size + point.debts.size > 0;
82	    const portfolio = point.known && calculated?.before && date < calculated.before ? calculatedOn.get(date) : undefined;
83	    if (portfolio) add(point.assets, portfolio.currency_code, BigInt(portfolio.total_minor));
84	    return point;
85	  });
86	}
