88	// Net worth now, from the same inputs as the Overview total: resolved account balances (one without a usable balance
89	// is left out, as there) and the valuations that count today.
90	export function currentNetWorth(date: string, accounts: { currency_code: string; balance: { amount_minor: string | null } }[],
91	  valuations: { amountMinor: bigint; currencyCode: string; debt: boolean }[]): NetWorthPoint {
92	  const point: NetWorthPoint = { date, accounts: new Map(), assets: new Map(), debts: new Map(), known: false };
93	  for (const account of accounts) if (account.balance.amount_minor !== null) add(point.accounts, account.currency_code, BigInt(account.balance.amount_minor));
94	  for (const valuation of valuations) add(valuation.debt ? point.debts : point.assets, valuation.currencyCode, valuation.amountMinor);
95	  point.known = point.accounts.size + point.assets.size + point.debts.size > 0;
96	  return point;
97	}
