99	export function netWorth(point: NetWorthPoint): Map<string, bigint> {
100	  const total = new Map<string, bigint>();
101	  for (const map of [point.accounts, point.assets, point.debts]) for (const [currency, amount] of map) add(total, currency, amount);
102	  return total;
103	}
