7	// Money moved between the owner's own accounts is a transfer, never income or spending.
8	// Detection is deterministic and IBAN-only: a row's counterparty IBAN is one of the owner's
9	// own accounts. Every decision goes through the audited link RPCs, so each one can be undone.
10	
11	export const MATCH_DAYS = 3;
12	const IBAN = /^[A-Z]{2}[0-9]{2}[A-Z0-9]{8,30}$/;
13	
14	export function normalizeIban(value: string) {
15	  const iban = value.replace(/\s/g, "").toUpperCase();
16	  return IBAN.test(iban) ? iban : null;
17	}
18	
19	/** Every IBAN-shaped value in an original source row (counterparty columns differ per bank). */
20	export function sourceIbans(row: unknown) {
21	  if (!row || typeof row !== "object") return [];
22	  return Object.values(row).flatMap(value => typeof value === "string" ? [normalizeIban(value)].filter((iban): iban is string => Boolean(iban)) : []);
23	}
