25	export type TransferCandidate = {
26	  id: string; version: number; accountId: string; postedOn: string; amountMinor: bigint; currencyCode: string;
27	  reviewReasons: string[]; ibans: string[]; text?: string; counterparty?: string;
28	};
29	
30	// Without an IBAN, only the bank's own wording proves own money: a cash machine, or Scalable Capital
31	// once the owner connected Scalable (their withdrawals arrive without the broker's IBAN).
32	const CASH = /\b(bargeldauszahlung|bargeldeinzahlung|geldautomat|cash withdrawal|atm withdrawal|cash deposit)\b/i;
33	const SCALABLE = /\bscalable capital\b/i;
34	export type NamedAccount = "cash" | "scalable";
35	export const NAMED_LABELS: Record<NamedAccount, string> = { cash: "Cash", scalable: "Scalable Capital" };
36	export type OwnAccounts = { tracked: Map<string, string>; untracked: Map<string, string> }; // IBAN → account id / identifier id
37	
38	const days = (a: string, b: string) => Math.abs(Date.parse(a) - Date.parse(b)) / 86400000;
39	
40	/** Every posted leg in the workspace, so a lone leg can tell whether its other side exists. */
41	export type Leg = Pick<TransferCandidate, "id" | "accountId" | "postedOn" | "amountMinor" | "currencyCode">;
42	
43	export function findOwnTransfers(rows: TransferCandidate[], own: OwnAccounts, legs: Leg[] = rows, options: { scalable?: boolean } = {}) {
44	  // The posting account's own IBAN often appears in its row too; only the other side counts.
45	  const counterparts = (row: TransferCandidate) => row.ibans.filter(iban => own.tracked.get(iban) !== row.accountId);
46	  const points = (row: TransferCandidate, accountId: string) => counterparts(row).some(iban => own.tracked.get(iban) === accountId);
47	  const matches = (out: TransferCandidate, into: TransferCandidate) => out.amountMinor < 0n && into.amountMinor === -out.amountMinor
48	    && out.currencyCode === into.currencyCode && out.accountId !== into.accountId && days(out.postedOn, into.postedOn) <= MATCH_DAYS;
49	  const used = new Set<string>();
50	  const pairs: { outId: string; inId: string }[] = [];
51	  const outs = rows.filter(row => row.amountMinor < 0n), ins = rows.filter(row => row.amountMinor > 0n);
52	  const take = (out: TransferCandidate, into: TransferCandidate) => { used.add(out.id); used.add(into.id); pairs.push({ outId: out.id, inId: into.id }); };
53	
54	  // IBAN-proven pairs first, closest date wins.
55	  for (const out of outs) {
56	    const proven = ins.filter(into => !used.has(into.id) && matches(out, into) && (points(out, into.accountId) || points(into, out.accountId)))
57	      .sort((a, b) => days(out.postedOn, a.postedOn) - days(out.postedOn, b.postedOn) || a.id.localeCompare(b.id));
58	    if (!used.has(out.id) && proven[0]) take(out, proven[0]);
59	  }
60	  // A leg whose other side is missing: the counterparty is an own account, and no opposite
61	  // leg exists in that account within the window. Untracked accounts are named by identifier;
62	  // tracked accounts by IBAN.
63	  const unpaired = (row: TransferCandidate, accountId: string) => !legs.some(other => other.id !== row.id && other.accountId === accountId
64	    && other.currencyCode === row.currencyCode && other.amountMinor === -row.amountMinor && days(row.postedOn, other.postedOn) <= MATCH_DAYS);
65	  const single = rows.flatMap((row): { transactionId: string; identifierId?: string; iban?: string }[] => {
66	    if (used.has(row.id)) return [];
67	    const identifierId = counterparts(row).map(iban => own.untracked.get(iban)).find(Boolean);
68	    if (identifierId) return [{ transactionId: row.id, identifierId }];
69	    const iban = counterparts(row).find(item => own.tracked.has(item));
70	    const accountId = iban ? own.tracked.get(iban) : undefined;
71	    return iban && accountId && unpaired(row, accountId) ? [{ transactionId: row.id, iban }] : [];
72	  });
73	  const marked = new Set(single.map(item => item.transactionId));
74	  const named = rows.flatMap((row): { transactionId: string; account: NamedAccount }[] => {
75	    if (used.has(row.id) || marked.has(row.id) || counterparts(row).some(iban => own.tracked.has(iban) || own.untracked.has(iban))) return [];
76	    if (CASH.test(row.text ?? "")) return [{ transactionId: row.id, account: "cash" }];
77	    if (options.scalable && SCALABLE.test(`${row.counterparty ?? ""} ${row.text ?? ""}`)) return [{ transactionId: row.id, account: "scalable" }];
78	    return [];
79	  });
80	  return { pairs, single, named };
81	}
