83	const nameKey = (name: string) => name.normalize("NFD").replace(/\p{M}/gu, "").replace(/\s+/g, " ").trim().toLowerCase();
84	
85	/**
86	 * Rows from a name the owner already sent money under to one of their own IBANs (their name on an old or
87	 * untracked account). A name alone is weak evidence, so these are only ever suggestions for the owner to accept.
88	 * `seen` are rows that already prove an own account (including linked transfers); `answered` already have a card.
89	 */
90	export function ownNameSuggestions(rows: TransferCandidate[], seen: TransferCandidate[], own: OwnAccounts, answered = new Set<string>()) {
91	  const names = new Map<string, string>();
92	  for (const row of seen) {
93	    const other = row.ibans.filter(iban => own.tracked.get(iban) !== row.accountId);
94	    if (row.counterparty?.trim() && other.some(iban => own.tracked.has(iban) || own.untracked.has(iban))) names.set(nameKey(row.counterparty), row.counterparty.trim());
95	  }
96	  // A bank can put the holder's own name on a payment with no real other side (Revolut card refunds);
97	  // a transfer the owner made names them in the description too.
98	  return rows.flatMap(row => {
99	    const name = row.counterparty ? names.get(nameKey(row.counterparty)) : undefined;
100	    return name && !answered.has(row.id) && nameKey(row.text ?? "").includes(nameKey(name)) ? [{ transactionId: row.id, name }] : [];
101	  });
102	}
