106	export async function loadOwnAccounts(db: SupabaseClient, workspaceId: string): Promise<OwnAccounts> {
107	  const [identifiers, bank, accounts] = await Promise.all([
108	    db.from("own_account_identifiers").select("id, account_id, iban").eq("workspace_id", workspaceId),
109	    db.from("bank_connection_accounts").select("iban, account_name, currency_code").eq("workspace_id", workspaceId).not("iban", "is", null),
110	    db.from("accounts").select("id, name, currency_code").eq("workspace_id", workspaceId),
111	  ]);
112	  for (const result of [identifiers, bank, accounts]) if (result.error) throw new Error(result.error.message);
113	  const tracked = new Map<string, string>(), untracked = new Map<string, string>();
114	  // A bank sync imports into the account with the bank's name and currency (see bankAccountNames).
115	  for (const row of bank.data ?? []) {
116	    const account = accounts.data?.find(item => item.name === row.account_name && item.currency_code === row.currency_code);
117	    const iban = normalizeIban(row.iban ?? "");
118	    if (account && iban) tracked.set(iban, account.id);
119	  }
120	  for (const row of identifiers.data ?? []) {
121	    if (row.account_id) tracked.set(row.iban, row.account_id); else untracked.set(row.iban, row.id);
122	  }
123	  return { tracked, untracked };
124	}
