126	type Row = { id: string; version: number; account_id: string; posted_on: string; amount_minor: string; currency_code: string; review_reasons: string[] | null; description: string;
127	  transaction_sources: { source_transactions: { original_row: unknown } | null }[] | null };
128	
129	/** The counterparty name a bank sync stores on its original row; other imports leave it out. */
130	const counterpartyOf = (row: unknown) => {
131	  const value = row && typeof row === "object" ? (row as { counterparty?: unknown }).counterparty : undefined;
132	  return typeof value === "string" && value.trim() ? value.trim() : undefined;
133	};
