135	async function loadRows(db: SupabaseClient, workspaceId: string, kind: "ordinary" | "transfer") {
136	  const rows: TransferCandidate[] = [];
137	  for (let from = 0; from < MAX_ROWS; from += PAGE) {
138	    let query = db.from("transactions")
139	      .select("id, version, account_id, posted_on, amount_minor::text, currency_code, review_reasons, description, transaction_sources(source_transactions(original_row))")
140	      .eq("workspace_id", workspaceId).eq("status", "posted").eq("kind", kind);
141	    if (kind === "ordinary") query = query.is("transfer_id", null).is("refund_of_id", null);
142	    const { data, error } = await query.order("posted_on", { ascending: false }).order("id").range(from, from + PAGE - 1);
143	    if (error) throw new Error(error.message);
144	    for (const row of (data ?? []) as unknown as Row[]) {
145	      const reviewReasons = row.review_reasons ?? [];
146	      if (kind === "ordinary" && reviewReasons.some(reason => reason !== "source_transfer")) continue;
147	      const originals = (row.transaction_sources ?? []).map(source => source.source_transactions?.original_row);
148	      rows.push({ id: row.id, version: row.version, accountId: row.account_id, postedOn: row.posted_on, amountMinor: BigInt(row.amount_minor),
149	        currencyCode: row.currency_code, reviewReasons, ibans: [...new Set(originals.flatMap(sourceIbans))], text: row.description, counterparty: originals.map(counterpartyOf).find(Boolean) });
150	    }
151	    if ((data ?? []).length < PAGE) break;
152	  }
153	  return rows;
154	}
155	
156	export const loadTransferCandidates = (db: SupabaseClient, workspaceId: string) => loadRows(db, workspaceId, "ordinary");
157	
158	/** Every posted leg, whatever its review state, so a lone leg can see whether its other side exists. */
159	async function loadLegs(db: SupabaseClient, workspaceId: string): Promise<Leg[]> {
160	  const legs: Leg[] = [];
161	  for (let from = 0; from < MAX_ROWS; from += PAGE) {
162	    const { data, error } = await db.from("transactions")
163	      .select("id, account_id, posted_on, amount_minor::text, currency_code")
164	      .eq("workspace_id", workspaceId).eq("status", "posted").order("id").range(from, from + PAGE - 1);
165	    if (error) throw new Error(error.message);
166	    for (const row of data ?? []) legs.push({ id: row.id, accountId: row.account_id, postedOn: row.posted_on, amountMinor: BigInt(row.amount_minor), currencyCode: row.currency_code });
167	    if ((data ?? []).length < PAGE) break;
168	  }
169	  return legs;
170	}
