172	export const ownTransferPayloadSchema = z.object({ transactionId: z.uuid(), name: z.string().trim().min(1).max(120) }).strict();
173	
174	/** Raises one "your own money?" card per row, once: a declined card is never raised again. */
175	async function proposeOwnNames(db: SupabaseClient, workspaceId: string, rows: TransferCandidate[], seen: TransferCandidate[], own: OwnAccounts) {
176	  const known = await db.from("agent_proposals").select("conflict_key").eq("workspace_id", workspaceId).is("run_id", null).eq("kind", "own_transfer").limit(5000);
177	  if (known.error) throw new Error(known.error.message);
178	  const answered = new Set((known.data ?? []).map(row => String(row.conflict_key).replace(/^own_transfer:/, "")));
179	  const found = ownNameSuggestions(rows, seen, own, answered);
180	  if (!found.length) return 0;
181	  const { locale } = await loadWorkspaceSettings(db, workspaceId);
182	  const byId = new Map(rows.map(row => [row.id, row]));
183	  const cards = found.map(({ transactionId, name }) => {
184	    const row = byId.get(transactionId)!, money = formatMoney(row.amountMinor < 0n ? -row.amountMinor : row.amountMinor, row.currencyCode, locale);
185	    return { workspace_id: workspaceId, agent: "chat", kind: "own_transfer", conflict_key: `own_transfer:${transactionId}`, confidence: 70,
186	      title: (row.amountMinor < 0n ? `${money} to ${name}: your own account?` : `${money} from ${name}: your own account?`).slice(0, 200),
187	      detail: `You sent money under the name ${name} to one of your own accounts before. If this is yours too, it moves to transfers and stops counting as ${row.amountMinor < 0n ? "spending" : "income"}.`,
188	      evidence: { facts: [], transactions: [{ id: row.id, date: row.postedOn, description: row.text ?? "", amountMinor: row.amountMinor.toString(), currency: row.currencyCode }], links: [] },
189	      payload: ownTransferPayloadSchema.parse({ transactionId, name }) };
190	  });
191	  const { data, error } = await db.from("agent_proposals").insert(cards).select("id");
192	  // A concurrent sync raised the same card first.
193	  if (error && error.code !== "23505") throw new Error(error.message);
194	  return data?.length ?? 0;
195	}
