197	/** Find and link transfers between the owner's accounts. The service role acts for the owner. */
198	export async function linkOwnTransfers(db: SupabaseClient, workspaceId: string) {
199	  const [own, rows, legs, transfers, scalable] = await Promise.all([loadOwnAccounts(db, workspaceId), loadTransferCandidates(db, workspaceId), loadLegs(db, workspaceId),
200	    loadRows(db, workspaceId, "transfer"), db.from("scalable_connections").select("id", { count: "exact", head: true }).eq("workspace_id", workspaceId).eq("status", "active")]);
201	  if (scalable.error) throw new Error(scalable.error.message);
202	  const { pairs, single, named } = findOwnTransfers(rows, own, legs, { scalable: (scalable.count ?? 0) > 0 });
203	  const byId = new Map(rows.map(row => [row.id, row]));
204	  let linked = 0, marked = 0, skipped = 0;
205	  for (const pair of pairs) {
206	    const out = byId.get(pair.outId)!, into = byId.get(pair.inId)!;
207	    // The RPC rejects pairs it can't prove (e.g. a documented fee); those stay for manual review.
208	    const { error } = await db.rpc("link_transactions", { p_operation: "transfer", p_primary_id: out.id, p_expected_version: out.version,
209	      p_other_id: into.id, p_other_version: into.version, p_fx_rate_id: null, p_fees: [], p_request_id: randomUUID() });
210	    if (error) skipped++; else linked++;
211	  }
212	  for (const item of single) {
213	    const expectedVersion = byId.get(item.transactionId)!.version;
214	    const { error } = item.identifierId
215	      ? await db.rpc("mark_own_account_transfer", { p_transaction_id: item.transactionId, p_expected_version: expectedVersion, p_identifier_id: item.identifierId })
216	      : await db.rpc("mark_own_iban_transfer", { p_transaction_id: item.transactionId, p_expected_version: expectedVersion, p_iban: item.iban });
217	    if (error) skipped++; else marked++;
218	  }
219	  for (const item of named) {
220	    const { error } = await db.rpc("mark_own_named_transfer", { p_transaction_id: item.transactionId, p_expected_version: byId.get(item.transactionId)!.version, p_kind: item.account });
221	    if (error) skipped++; else marked++;
222	  }
223	  const handled = new Set([...pairs.flatMap(pair => [pair.outId, pair.inId]), ...single.map(item => item.transactionId), ...named.map(item => item.transactionId)]);
224	  const suggested = await proposeOwnNames(db, workspaceId, rows.filter(row => !handled.has(row.id)), [...rows, ...transfers], own);
225	  return { linked, marked, skipped, suggested };
226	}
