1	import Papa from "papaparse";
2	import { parseCsv, validateImportConfirmation, type ImportMapping } from "@/lib/import/csv";
3	import type { BankBalance, BankTransaction } from "./enable-banking";
4	
5	// A bank sync is an ordinary import: booked transactions become a canonical CSV with a
6	// fixed mapping, so dedupe, review, undo and source history work unchanged (issue #82).
7	const headers = ["id", "date", "description", "amount", "currency", "balance", "counterparty", "counterparty_iban"] as const;
8	
9	const clip = (value: string, length: number) => Array.from(value.replace(/\s+/g, " ").trim()).slice(0, length).join("");
10	
11	export function bankStatementRow(tx: BankTransaction) {
12	  const debit = tx.credit_debit_indicator === "DBIT";
13	  const magnitude = tx.transaction_amount.amount.replace(/^-/, "");
14	  // The indicator is the sign of record; without one, keep the amount's own sign.
15	  const amount = tx.credit_debit_indicator ? `${debit ? "-" : ""}${magnitude}` : tx.transaction_amount.amount;
16	  const counterparty = clip((debit ? tx.creditor?.name : tx.debtor?.name) ?? "", 200);
17	  const description = clip((tx.remittance_information ?? []).join(" "), 500) || counterparty || "Bank transaction";
18	  const balance = tx.balance_after_transaction?.currency === tx.transaction_amount.currency ? tx.balance_after_transaction.amount : "";
19	  return {
20	    id: clip(tx.entry_reference ?? tx.transaction_id ?? "", 500),
21	    date: tx.booking_date ?? tx.value_date ?? tx.transaction_date ?? "",
22	    description, amount, currency: tx.transaction_amount.currency, balance, counterparty,
23	    counterparty_iban: ((debit ? tx.creditor_account?.iban : tx.debtor_account?.iban) ?? "").replace(/\s/g, ""),
24	  } satisfies Record<(typeof headers)[number], string>;
25	}
26	
27	// Deterministic bytes: the same bank data always hashes to the same import, so a repeated
28	// sync of an unchanged window is a no-op at the imports(file_hash) unique index.
29	// The closing balance rides on the latest booked row's balance column, so it lands in
30	// balance_snapshots with that import's provenance and undoes with it.
31	export function bankStatement(transactions: BankTransaction[], account: { accountName: string; currencyCode: string; calendarTimezone?: string }, closing?: BankBalance) {
32	  const byId = new Map<string, ReturnType<typeof bankStatementRow>>();
33	  const unidentified: ReturnType<typeof bankStatementRow>[] = [];
34	  for (const tx of transactions) {
35	    if (tx.status !== "BOOK") continue;
36	    const row = bankStatementRow(tx);
37	    if (!row.date) throw new Error("Booked bank transaction has no date");
38	    if (row.id) byId.set(row.id, row); else unidentified.push(row);
39	  }
40	  const rows = [...byId.values(), ...unidentified].sort((a, b) => a.date.localeCompare(b.date) || a.id.localeCompare(b.id)
41	    || a.amount.localeCompare(b.amount) || a.description.localeCompare(b.description));
42	  if (!rows.length) return null;
43	  const last = rows[rows.length - 1];
44	  if (closing && !last.balance && last.currency === account.currencyCode && closing.balance_amount.currency === account.currencyCode
45	    && (!closing.reference_date || closing.reference_date >= last.date)) last.balance = closing.balance_amount.amount;
46	  const csv = Papa.unparse({ fields: [...headers], data: rows.map(row => headers.map(header => row[header])) }, { newline: "\n" });
47	  const mapping: ImportMapping = {
48	    accountName: account.accountName, currencyCode: account.currencyCode,
49	    dateColumn: "date", descriptionColumn: "description", amountColumn: "amount", currencyColumn: "currency",
50	    balanceColumn: "balance", merchantColumn: "counterparty", externalIdColumn: "id",
51	    dateFormat: "iso", amountSign: "signed", numericConvention: "decimal-dot",
52	    ...(account.calendarTimezone ? { calendarTimezone: account.calendarTimezone } : {}),
53	  };
54	  const parsed = parseCsv(csv);
55	  return { csv, rowCount: parsed.length, lastBookedOn: last.date, mapping: validateImportConfirmation(parsed, mapping) };
56	}
57	
58	// Booked balances first. Some banks (Revolut) publish only an available balance, so fall back to it.
59	// ponytail: an available balance can include an overdraft or credit line; exclude per bank if that bites.
60	export function preferredBalance(balances: BankBalance[], currencyCode: string) {
61	  const order = ["CLBD", "ITBD", "XPCD", "CLAV", "ITAV"];
62	  const usable = balances.filter(balance => balance.balance_amount.currency === currencyCode && order.includes(balance.balance_type));
63	  return usable.sort((a, b) => order.indexOf(a.balance_type) - order.indexOf(b.balance_type))[0];
64	}
