28	// Banks decide how far back they answer; under PSD2 most share full history only shortly after
29	// consent (when the first sync runs) and about 90 days after that. So with no cursor ask for
30	// everything, falling back to 90 days for banks that reject an old date_from.
31	const FULL_HISTORY_FROM = "2000-01-01";
32	async function bookedSince(client: EnableBankingClient, uid: string, lastBookedOn: string | null, today: string, psu?: PsuContext) {
33	  // Re-fetch a week of overlap: late-booked rows dedupe on the bank id.
34	  if (lastBookedOn) return client.bookedTransactions(uid, daysBefore(lastBookedOn, 7), psu);
35	  try { return await client.bookedTransactions(uid, FULL_HISTORY_FROM, psu); } catch (error) {
36	    if (!(error instanceof EnableBankingError) || error.expired || error.rateLimited || error.status < 400 || error.status >= 500) throw error;
37	    return client.bookedTransactions(uid, daysBefore(today, 90), psu);
38	  }
39	}
