41	async function stageBankImports(connectionId: string, workspaceId: string, psu?: PsuContext): Promise<{ imports: BankImport[]; error: string | null }> {
42	  "use step";
43	  const db = serviceDb();
44	  const connection = await db.from("bank_connections").select("status, valid_until").eq("id", connectionId).eq("workspace_id", workspaceId).single();
45	  if (connection.error) throw new Error(connection.error.message);
46	  if (connection.data.status !== "active") return { imports: [], error: null };
47	  if (Date.parse(connection.data.valid_until) <= Date.now()) {
48	    await db.from("bank_connections").update({ status: "expired", last_error: "Bank consent expired; reconnect to keep syncing" }).eq("id", connectionId);
49	    return { imports: [], error: null };
50	  }
51	  // Marks the sync as running for the UI until finishBankSync sets last_synced_at.
52	  const started = await db.from("bank_connections").update({ sync_started_at: new Date().toISOString() }).eq("id", connectionId).eq("workspace_id", workspaceId);
53	  if (started.error) throw new Error(started.error.message);
54	  const accounts = await db.from("bank_connection_accounts").select("provider_account_uid, currency_code, account_name, last_booked_on").eq("connection_id", connectionId);
55	  if (accounts.error) throw new Error(accounts.error.message);
56	  const settings = await loadWorkspaceSettings(db, workspaceId);
57	  const client = await enableBankingClient();
58	  const today = isoDay(new Date());
59	  const imports: BankImport[] = [];
60	  try {
61	    for (const account of accounts.data) {
62	      const closing = preferredBalance(await client.balances(account.provider_account_uid, psu), account.currency_code);
63	      const transactions = await bookedSince(client, account.provider_account_uid, account.last_booked_on, today, psu);
64	      const statement = bankStatement(transactions, { accountName: account.account_name, currencyCode: account.currency_code, calendarTimezone: settings.timezone }, closing);
65	      if (!statement) continue;
66	      if (statement.rowCount > 10_000) throw new Error("Bank returned more than 10,000 transactions for one account");
67	      const bytes = Buffer.from(statement.csv, "utf8");
68	      const hash = createHash("sha256").update(bytes).digest("hex");
69	      const storagePath = `${workspaceId}/${hash}.csv`;
70	      const upload = await db.storage.from("imports").upload(storagePath, bytes, { contentType: "text/csv", upsert: false });
71	      if (upload.error && !/already exists|duplicate/i.test(upload.error.message)) throw new Error(upload.error.message);
72	      const inserted = await db.from("imports").insert({ workspace_id: workspaceId, filename: `${account.account_name} bank sync ${today}.csv`, storage_path: storagePath,
73	        file_hash: hash, status: "queued", mapping: statement.mapping, total_rows: statement.rowCount }).select("id").single();
74	      let importId = inserted.data?.id as string | undefined;
75	      if (inserted.error) {
76	        if (inserted.error.code !== "23505") throw new Error(inserted.error.message);
77	        // Identical window already imported: a no-op, unless an earlier attempt never ran it.
78	        const existing = await db.from("imports").select("id, status").eq("workspace_id", workspaceId).eq("file_hash", hash).neq("status", "undone").single();
79	        if (existing.error) throw new Error(existing.error.message);
80	        importId = existing.data.status === "queued" ? existing.data.id : undefined;
81	      }
82	      if (importId) imports.push({ importId, rowCount: statement.rowCount, uid: account.provider_account_uid, lastBookedOn: statement.lastBookedOn });
83	    }
84	    return { imports, error: null };
85	  } catch (error) {
86	    if (error instanceof EnableBankingError && error.expired) {
87	      await db.from("bank_connections").update({ status: "expired", last_error: "Bank consent expired; reconnect to keep syncing" }).eq("id", connectionId);
88	      return { imports, error: null };
89	    }
90	    // Rate limits (about 4 background fetches a day) and bank errors wait for the next run.
91	    const message = error instanceof EnableBankingError && error.rateLimited ? "The bank rate limit was reached; the next sync will retry" : String(error instanceof Error ? error.message : error);
92	    return { imports, error: message.slice(0, 1000) };
93	  }
94	}
