96	async function finishBankSync(connectionId: string, workspaceId: string, imports: BankImport[], error: string | null) {
97	  "use step";
98	  const db = serviceDb();
99	  for (const item of imports) {
100	    const imported = await db.from("imports").select("status").eq("id", item.importId).eq("workspace_id", workspaceId).single();
101	    if (imported.error) throw new Error(imported.error.message);
102	    // Only advance the window once the rows are actually in; a failed import re-fetches next time.
103	    if (imported.data.status !== "completed") continue;
104	    const advanced = await db.from("bank_connection_accounts").update({ last_booked_on: item.lastBookedOn }).eq("connection_id", connectionId).eq("provider_account_uid", item.uid);
105	    if (advanced.error) throw new Error(advanced.error.message);
106	  }
107	  const done = await db.from("bank_connections").update({ last_synced_at: new Date().toISOString(), last_error: error }).eq("id", connectionId).eq("workspace_id", workspaceId);
108	  if (done.error) throw new Error(done.error.message);
109	}
