1	import { serviceDb } from "@/lib/bank/server";
2	import { calendarDate } from "@/lib/finance/calendar";
3	import { loadWorkspaceSettings } from "@/lib/settings";
4	import { ScalableError } from "./client";
5	import { investmentsWatchlist, readTransactions, tradingAccess } from "./live";
6	import { cashSchema, holdingsSchema, overviewSchema, scalableWealth, type ScalableExtras } from "./portfolio";
7	import { withScalable } from "./server";
8	
9	/**
10	 * One sync: read holdings, totals and cash from Scalable, then write them as dated wealth records in
11	 * one database call. Market moves are valuations, not income; deposits and withdrawals are transfers
12	 * on the bank side. Errors are kept on the connection for the UI and rethrown.
13	 */
14	export async function syncScalable(connectionId: string, workspaceId: string) {
15	  const db = serviceDb();
16	  try {
17	    const { timezone } = await loadWorkspaceSettings(db, workspaceId);
18	    const previous = await db.from("scalable_connections").select("portfolio").eq("workspace_id", workspaceId).not("portfolio", "is", null);
19	    const { snapshot, extras, access } = await withScalable(connectionId, workspaceId, async mcp => {
20	      // Activity and watchlist are extras: a failure there never stops the valuation sync.
21	      // So are the access level the chat uses to offer trading, and only a known level is saved.
22	      const [holdings, overview, cash, activity, watchlist, access] = await Promise.all([mcp.callTool("get_portfolio_holdings"), mcp.callTool("get_portfolio_overview", { includeYearToDate: true }),
23	        mcp.callTool("get_portfolio_cash_breakdown"), mcp.callTool("list_portfolio_transactions", { pageSize: 8 }).then(readTransactions).catch(() => undefined),
24	        investmentsWatchlist(mcp).catch(() => undefined), tradingAccess(mcp).catch(() => undefined)]);
25	      return { access, snapshot: { holdings: holdingsSchema.parse(holdings), overview: overviewSchema.parse(overview), cash: cashSchema.parse(cash) },
26	        extras: { ...(activity ? { activity: activity.map(({ id, date, status, type, description, shares, amountMinor, currencyCode }) => ({ id, date, status, type, description, shares, amountMinor, currencyCode })) } : {}),
27	          ...(watchlist ? { watchlist: watchlist.items.slice(0, 12).map(item => ({ isin: item.isin, name: item.name, priceMinor: item.quote?.priceMinor ?? null, currencyCode: item.quote?.currencyCode ?? "EUR", dayPercent: item.dayPercent })) } : {}) } };
28	    });
29	    const { items, portfolio } = scalableWealth(snapshot, workspaceId, calendarDate(new Date(), timezone));
30	    const known = new Set([...(previous.data ?? []).flatMap(row => { const ids = (row.portfolio as ScalableExtras | null); return [...(ids?.knownItemIds ?? []), ...(ids?.itemIds ?? [])]; }), ...items.map(item => item.id)]);
31	    const { data, error } = await db.rpc("sync_scalable_wealth", { p_connection_id: connectionId, p_items: items, p_portfolio: { ...portfolio, ...extras, knownItemIds: [...known] } });
32	    if (error) throw new Error(error.message);
33	    if (access) {
34	      const saved = await db.from("scalable_connections").update({ trading_access: access }).eq("id", connectionId);
35	      if (saved.error) throw new Error(saved.error.message);
36	    }
37	    return { changed: data as number, portfolio };
38	  } catch (error) {
39	    // An ended login is already recorded as expired by withScalable.
40	    if (!(error instanceof ScalableError && error.expired))
41	      await db.from("scalable_connections").update({ last_error: "The Scalable sync failed. It retries on the next sync." }).eq("id", connectionId);
42	    throw error;
43	  }
44	}
