1	import { serviceDb } from "@/lib/bank/server";
2	import { decryptToken, encryptToken } from "@/lib/bank/token-crypto";
3	import { getEnv } from "@/lib/env";
4	import { refreshTokens, scalableMcp, ScalableError, type ScalableMcp, type ScalableTokens } from "./client";
5	
6	export const scalableRedirectUri = () => new URL("/api/scalable/callback", getEnv().NEXT_PUBLIC_APP_URL).toString();
7	
8	export function scalableConfigured() {
9	  return Boolean(process.env.BANK_TOKEN_ENCRYPTION_KEY && process.env.SUPABASE_SERVICE_ROLE_KEY);
10	}
11	
12	export const sealTokens = (tokens: ScalableTokens, connectionId: string) => encryptToken(JSON.stringify(tokens), connectionId);
13	const openTokens = (sealed: string, connectionId: string) => JSON.parse(decryptToken(sealed, connectionId)) as ScalableTokens;
14	
15	const refreshing = new Map<string, Promise<ScalableTokens>>();
16	
17	/**
18	 * Runs `work` with a connected MCP session for an active connection. Refreshes the access token
19	 * when it is about to expire and stores the rotated tokens first, so a crash never loses them.
20	 * A rejected refresh marks the connection expired: the owner has to connect again. Long work passes `needsMs`,
21	 * because a token running out halfway looks the same as an ended login.
22	 */
23	export async function withScalable<T>(connectionId: string, workspaceId: string, work: (mcp: ScalableMcp) => Promise<T>, fetcher: typeof fetch = fetch, needsMs = 60_000): Promise<T> {
24	  const db = serviceDb();
25	  const row = await db.from("scalable_connections").select("client_id, tokens_encrypted").eq("id", connectionId)
26	    .eq("workspace_id", workspaceId).eq("status", "active").single();
27	  if (row.error || !row.data?.tokens_encrypted) throw new ScalableError("Scalable is not connected", 404);
28	  let tokens = openTokens(row.data.tokens_encrypted, connectionId);
29	  if (tokens.expiresAt - Date.now() < needsMs) {
30	    // Chat tools run in parallel; one refresh per connection, so a rotated refresh token is never spent twice.
31	    const stale = tokens, clientId = row.data.client_id;
32	    const pending = refreshing.get(connectionId) ?? (async () => {
33	      if (!stale.refreshToken) return expire(connectionId, "The Scalable login ended. Connect again.");
34	      let fresh: ScalableTokens;
35	      try { fresh = await refreshTokens({ clientId, refreshToken: stale.refreshToken }, fetcher); } catch (error) {
36	        if (error instanceof ScalableError && error.expired) return expire(connectionId, "The Scalable login ended. Connect again.");
37	        throw error;
38	      }
39	      const saved = await db.from("scalable_connections").update({ tokens_encrypted: sealTokens(fresh, connectionId) }).eq("id", connectionId).eq("status", "active");
40	      if (saved.error) throw new Error(saved.error.message);
41	      return fresh;
42	    })().finally(() => refreshing.delete(connectionId));
43	    refreshing.set(connectionId, pending);
44	    tokens = await pending;
45	  }
46	  const mcp = scalableMcp(tokens.accessToken, fetcher);
47	  try {
48	    await mcp.connect();
49	    return await work(mcp);
50	  } catch (error) {
51	    if (error instanceof ScalableError && error.expired) return expire(connectionId, "Scalable rejected the login. Connect again.");
52	    throw error;
53	  }
54	}
55	
56	async function expire(connectionId: string, message: string): Promise<never> {
57	  await serviceDb().from("scalable_connections").update({ status: "expired", tokens_encrypted: null, last_error: message }).eq("id", connectionId);
58	  throw new ScalableError(message, 401, true);
59	}
