6	// Scalable MCP answers, validated down to the fields Moneo uses. Amounts arrive as JSON numbers.
7	const money = z.number().finite();
8	export const holdingsSchema = z.object({
9	  holdings: z.array(z.object({
10	    isin: z.string().min(1), name: z.string().min(1), fifoPrice: money.nullable().optional(), valuation: money, valuationCurrency: z.string().regex(/^[A-Z]{3}$/),
11	    currentQuote: z.object({ currency: z.string().regex(/^[A-Z]{3}$/), midPrice: money }), position: z.object({ filled: money }),
12	  })),
13	  cryptoHoldings: z.array(z.object({ ticker: z.string(), name: z.string(), position: z.object({ filled: money }).nullable() })).default([]),
14	});
15	export const overviewSchema = z.object({
16	  valuation: z.object({ total: money, securities: money.default(0), crypto: money.default(0) }),
17	  timestamps: z.object({ valuationTimestampUtc: z.string() }).partial().optional(),
18	  performance: z.array(z.object({ timeframe: z.string(), simpleAbsoluteReturn: money.nullable() })).default([]),
19	});
20	export const cashSchema = z.object({ cash: z.object({ cashBalance: money }) });
21	
22	export type ScalableSnapshot = { holdings: z.infer<typeof holdingsSchema>; overview: z.infer<typeof overviewSchema>; cash: z.infer<typeof cashSchema> };
23	
24	/** Shortest exact decimal text for a JSON number (never exponent notation). */
25	export function decimalText(value: number) {
26	  const text = String(Math.abs(value));
27	  return text.includes("e") ? Math.abs(value).toFixed(18).replace(/\.?0+$/, "") : text;
28	}
29	const minor = (value: number, currency: string) => BigInt(Math.round(value * 10 ** minorDigits(currency)));
30	
31	/** Same workspace + position key → same wealth item id, so every sync and every reconnect updates one record. */
32	export function scalableItemId(workspaceId: string, key: string) {
33	  const hex = createHash("sha256").update(`scalable:${workspaceId}:${key}`).digest("hex");
34	  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-5${hex.slice(13, 16)}-${((parseInt(hex[16], 16) & 3) | 8).toString(16)}${hex.slice(17, 20)}-${hex.slice(20, 32)}`;
35	}
36	
37	export type ScalableWealthItem = { id: string; kind: "holding" | "asset"; name: string; currency_code: string; amount_minor: string;
38	  quantity_text: string | null; unit_price_text: string | null; cost_basis_minor: string | null; as_of: string };
39	
40	/**
41	 * Wealth records for one Scalable portfolio on `asOf`: each security at quantity × live price,
42	 * plus uninvested cash and crypto as assets. Their sum is Scalable's own portfolio total (to the cent).
43	 */
44	export function scalableWealth({ holdings, overview, cash }: ScalableSnapshot, workspaceId: string, asOf: string, currency = "EUR") {
45	  const items: ScalableWealthItem[] = holdings.holdings.filter(holding => holding.position.filled > 0).map(holding => {
46	    const quantity = decimalText(holding.position.filled), price = decimalText(holding.currentQuote.midPrice), code = holding.currentQuote.currency;
47	    return { id: scalableItemId(workspaceId, `isin:${holding.isin}`), kind: "holding", name: Array.from(holding.name).slice(0, 120).join(""), currency_code: code,
48	      amount_minor: holdingValue(quantity, price, code).toString(), quantity_text: quantity, unit_price_text: price,
49	      cost_basis_minor: holding.fifoPrice ? minor(holding.fifoPrice * holding.position.filled, code).toString() : null, as_of: asOf };
50	  });
51	  const asset = (key: string, name: string, value: number): ScalableWealthItem => ({ id: scalableItemId(workspaceId, key), kind: "asset", name, currency_code: currency,
52	    amount_minor: minor(Math.max(value, 0), currency).toString(), quantity_text: null, unit_price_text: null, cost_basis_minor: null, as_of: asOf });
53	  const coins = holdings.cryptoHoldings.filter(coin => (coin.position?.filled ?? 0) > 0).map(coin => coin.name);
54	  if (overview.valuation.crypto > 0) items.push(asset("crypto", `Scalable crypto${coins.length ? ` (${coins.join(", ")})` : ""}`.slice(0, 120), overview.valuation.crypto));
55	  items.push(asset("cash", "Scalable cash", cash.cash.cashBalance));
56	  const portfolio = {
57	    currency, asOf, valuedAt: overview.timestamps?.valuationTimestampUtc ?? null,
58	    totalMinor: minor(overview.valuation.total, currency).toString(), securitiesMinor: minor(overview.valuation.securities, currency).toString(),
59	    cryptoMinor: minor(overview.valuation.crypto, currency).toString(), cashMinor: minor(cash.cash.cashBalance, currency).toString(),
60	    performance: overview.performance.flatMap(entry => entry.simpleAbsoluteReturn === null ? [] : [{ timeframe: entry.timeframe, returnMinor: minor(entry.simpleAbsoluteReturn, currency).toString() }]),
61	  };
62	  return { items, portfolio };
63	}
64	/** What the Wealth page shows beside the totals: recent trades and cash moves, and the watchlist, as of the last sync. */
65	export type ScalableExtras = {
66	  activity?: { id: string; date: string; status: string; type: string; description: string | null; shares: string | null; amountMinor: string | null; currencyCode: string }[];
67	  watchlist?: { isin: string; name: string; priceMinor: string | null; currencyCode: string; dayPercent: number | null }[];
68	  /** Every item id a sync ever wrote, so the value chart keeps positions that were sold since. */
69	  knownItemIds?: string[]; itemIds?: string[];
70	};
71	export type ScalablePortfolio = ReturnType<typeof scalableWealth>["portfolio"] & ScalableExtras;
