9	// Past daily values of a Scalable portfolio, worked out from its own transactions and price charts. This is a
10	// calculation, not a record: it is saved apart from wealth_items and wealth_events, and only after replaying
11	// everything lands on today's real holdings and cash.
12	
13	const CURRENCY = "EUR";
14	const PAGE_SIZE = 100, MAX_PAGES = 1000;
15	// Sparse far back, close to daily recently; merged so every date gets the best price available.
16	const TIMEFRAMES = ["max", "one_year", "six_months", "year_to_date"];
17	
18	type Chart = { currency: string; points: { at: string; price: string }[] };
19	export type HistoryRow = { id: string; at: string; currency?: string } & (
20	  | { kind: "security"; isin: string; side: string; quantity: string | null; amountText: string }
21	  | { kind: "cash"; quantity?: undefined; amountText: string }
22	  // Scalable holds crypto as shares of an ETP, so `isin` and `quantity` are the ETP's.
23	  | { kind: "crypto"; isin: string; side: string; quantity: string | null; amountText: string });
24	export type HistoryInput = {
25	  rows: HistoryRow[]; charts: Record<string, Chart>;
26	  holdings: { isin: string; filled: number | string; currency?: string }[];
27	  cashBalance: number | string; timeZone: string;
28	  /** The date of the first real synced value: days stop before it. */
29	  before: string;
30	};
31	export type HistoryDay = { date: string; securitiesMinor: bigint; cryptoMinor: bigint; cashMinor: bigint; totalMinor: bigint };
32	export type HistoryResult = { ok: true; days: HistoryDay[] } | { ok: false; reason: string };
33	
34	const decimal = z.union([z.number().finite(), z.string().regex(/^-?\d+(\.\d+)?$/)]);
35	const text = (value: number | string) => typeof value === "number" ? decimalText(value) : value;
36	const nextCursor = z.object({ nextCursor: z.string().nullish() });
37	const transactionsSchema = z.object({
38	  page: nextCursor.optional(),
39	  transactions: z.array(z.object({ id: z.string(), status: z.string(), currency: z.string().nullish(), isCancellation: z.boolean().nullish(), lastEventAt: z.string(),
40	    security: z.object({ isin: z.string(), side: z.string().nullish(), quantity: decimal.nullish(), amount: decimal.nullish() }).nullish(),
41	    cash: z.object({ amount: decimal.nullish() }).nullish() })).default([]),
42	  crypto: z.object({ page: nextCursor.optional(), transactions: z.array(z.object({ id: z.string(), status: z.string(), isCancellation: z.boolean().nullish(), lastEventAt: z.string(),
43	    side: z.string().nullish(), quantity: decimal.nullish(), amount: decimal.nullish() })).default([]) }).nullish(),
44	});
45	const holdingsSchema = z.object({
46	  holdings: z.array(z.object({ isin: z.string(), position: z.object({ filled: decimal }), currentQuote: z.object({ currency: z.string() }) })).default([]),
47	  cryptoHoldings: z.array(z.object({ ticker: z.string(), position: z.object({ filled: decimal }).nullish(), etpPositions: z.array(z.object({ isin: z.string(), position: z.object({ filled: decimal }).nullish() })).nullish() })).default([]),
48	});
49	const chartSchema = z.object({ currency: z.string().nullish(), dataPoints: z.array(z.object({ midPrice: decimal.nullish(), timestampUtc: z.string() })).default([]) });
50	const detailsSchema = z.object({ transaction: z.object({ security: z.object({ isin: z.string() }) }) });
51	const settled = (row: { status: string; isCancellation?: boolean | null }) => row.status === "SETTLED" && !row.isCancellation;
52	
53	/** Every settled trade and cash move. Security and crypto rows page separately, and a stream whose cursor runs out starts over if asked again. */
54	async function readRows(mcp: Pick<ScalableMcp, "callTool">) {
55	  const securities = new Map<string, HistoryRow>(), crypto = new Map<string, Omit<Extract<HistoryRow, { kind: "crypto" }>, "isin">>();
56	  let cursor: string | undefined, cryptoCursor: string | undefined, securitiesDone = false, cryptoDone = false;
57	  for (let page = 0; !securitiesDone || !cryptoDone; page++) {
58	    if (page === MAX_PAGES) throw new Error("Scalable transactions never finished paging");
59	    const reply = transactionsSchema.parse(await mcp.callTool("list_portfolio_transactions", { pageSize: PAGE_SIZE, ...(cursor ? { cursor } : {}), ...(cryptoCursor ? { cryptoCursor } : {}) }));
60	    if (!securitiesDone) for (const row of reply.transactions.filter(settled)) {
61	      const base = { id: row.id, at: row.lastEventAt, ...(row.currency ? { currency: row.currency } : {}) };
62	      if (row.security) securities.set(row.id, { ...base, kind: "security", isin: row.security.isin, side: row.security.side ?? "unknown", quantity: row.security.quantity == null ? null : text(row.security.quantity), amountText: String(row.security.amount ?? 0) });
63	      else if (row.cash) securities.set(row.id, { ...base, kind: "cash", amountText: String(row.cash.amount ?? 0) });
64	      // nonTradeSecurity and eltif rows say nothing reliable about quantity; if they matter, the check below fails.
65	    }
66	    if (!cryptoDone) for (const row of (reply.crypto?.transactions ?? []).filter(settled))
67	      crypto.set(row.id, { id: row.id, at: row.lastEventAt, kind: "crypto", side: row.side ?? "unknown", quantity: row.quantity == null ? null : text(row.quantity), amountText: String(row.amount ?? 0) });
68	    cursor = securitiesDone ? undefined : reply.page?.nextCursor || undefined;
69	    cryptoCursor = cryptoDone ? undefined : reply.crypto?.page?.nextCursor || undefined;
70	    securitiesDone = !cursor; cryptoDone = !cryptoCursor;
71	  }
72	  // A crypto row only names the coin; its details name the ETP that was actually bought.
73	  const rows = [...securities.values()];
74	  for (const row of crypto.values()) rows.push({ ...row, isin: detailsSchema.parse(await mcp.callTool("get_transaction_details", { transactionId: row.id })).transaction.security.isin });
75	  return rows;
76	}
