78	async function readChart(mcp: Pick<ScalableMcp, "callTool">, isin: string): Promise<Chart> {
79	  const replies: z.infer<typeof chartSchema>[] = [];
80	  for (const timeframe of TIMEFRAMES) replies.push(chartSchema.parse(await mcp.callTool("get_security_chart", { isin, timeframe })));
81	  const points = new Map(replies.flatMap(reply => reply.dataPoints.flatMap(point => point.midPrice != null && Number(point.midPrice) > 0 ? [[point.timestampUtc, text(point.midPrice)] as const] : [])));
82	  return { currency: replies.find(reply => reply.dataPoints.length && reply.currency !== CURRENCY)?.currency ?? CURRENCY, points: [...points].map(([at, price]) => ({ at, price })) };
83	}
