85	/** Everything the calculation needs, through Scalable's read tools only. A security chart that fails stops the run, to retry another day. */
86	export async function readHistoryInput(mcp: Pick<ScalableMcp, "callTool">, timeZone: string, before: string): Promise<HistoryInput> {
87	  const rows = await readRows(mcp);
88	  const holdings = holdingsSchema.parse(await mcp.callTool("get_portfolio_holdings"));
89	  const cash = z.object({ cash: z.object({ cashBalance: decimal }) }).parse(await mcp.callTool("get_portfolio_cash_breakdown"));
90	  // Scalable's coin figure shrinks over time, while the ETP's shares and price are exact, so those are what count.
91	  const unbacked = holdings.cryptoHoldings.find(coin => Number(coin.position?.filled ?? 0) > 0 && !coin.etpPositions?.some(etp => Number(etp.position?.filled ?? 0) > 0));
92	  if (unbacked) throw new Error(`${unbacked.ticker} is held without an ETP position`);
93	  const charts: Record<string, Chart> = {};
94	  for (const isin of new Set(rows.flatMap(row => row.kind === "cash" ? [] : [row.isin]))) charts[isin] = await readChart(mcp, isin);
95	  return { rows, charts, timeZone, before, cashBalance: cash.cash.cashBalance,
96	    holdings: [...holdings.holdings.map(holding => ({ isin: holding.isin, filled: holding.position.filled, currency: holding.currentQuote.currency })),
97	      ...holdings.cryptoHoldings.flatMap(coin => (coin.etpPositions ?? []).flatMap(etp => etp.position ? [{ isin: etp.isin, filled: etp.position.filled }] : []))] };
98	}
99	
100	// Shares and prices are fixed-point bigints with 18 decimals, so nothing drifts the way floats do.
101	const ONE = 10n ** 18n, TOLERANCE = 10n ** 12n /* a millionth of a share */, CASH_TOLERANCE = 100n /* one euro */;
102	const CENTS = 100n, CENT_SCALE = ONE / CENTS;
103	const scaled = (value: number | string) => { const ratio = decimalRatio(text(value)); return ratio.numerator * ONE / ratio.denominator; };
104	const decimalOf = (value: bigint) => `${value / ONE}.${(value % ONE).toString().padStart(18, "0")}`;
105	const value = (quantity: bigint, price: bigint) => holdingValue(decimalOf(quantity), decimalOf(price), CURRENCY);
106	const absolute = (minor: bigint) => minor < 0n ? -minor : minor;
107	/** The price per unit each trade paid, oldest first; a trade with no money or quantity says nothing. */
108	const tradePrices = (rows: Exclude<HistoryRow, { kind: "cash" }>[]) => rows.flatMap(row => {
109	  const minor = BigInt(toMinor(row.amountText, CURRENCY)), quantity = scaled(row.quantity!);
110	  return minor !== 0n && quantity > 0n ? [{ at: row.at, price: absolute(minor) * CENT_SCALE * ONE / quantity }] : [];
111	});
112	
113	type Prices = { points: { day: string; at: number; price: bigint }[]; next: number; current: bigint | null };
114	function pricesFrom(chart: Chart | undefined, timeZone: string, trades: { at: string; price: bigint }[] = []): Prices {
115	  const points = [...(chart?.points ?? []).map(point => ({ at: point.at, price: scaled(point.price) })), ...trades]
116	    .map(point => ({ day: calendarDate(point.at, timeZone), at: Date.parse(point.at), price: point.price })).sort((a, b) => a.at - b.at);
117	  return { points, next: 0, current: null };
118	}
119	/** The latest price on or before `date`, which must only move forward; a price is never interpolated. */
120	function priceOn(prices: Prices, date: string) {
121	  while (prices.next < prices.points.length && prices.points[prices.next].day <= date) prices.current = prices.points[prices.next++].price;
122	  return prices.current;
123	}
124	
125	function replay(input: HistoryInput): HistoryResult {
126	  const fail = (reason: string): HistoryResult => ({ ok: false, reason });
127	  const rows = [...input.rows].sort((a, b) => Date.parse(a.at) - Date.parse(b.at));
128	  if (!rows.length) return fail("Scalable returned no settled transactions");
129	
130	  for (const row of rows) {
131	    if (row.currency && row.currency !== CURRENCY) return fail(`A transaction is in ${row.currency}, and only ${CURRENCY} is supported`);
132	    if (row.kind === "cash") continue;
133	    if (row.side !== "BUY" && row.side !== "SELL") return fail(`Transaction ${row.id} has an unknown side: ${row.side}`);
134	    if (row.quantity === null) return fail(`Transaction ${row.id} has no quantity`);
135	  }
136	  for (const [isin, chart] of Object.entries(input.charts)) if (chart.currency !== CURRENCY) return fail(`${isin} is priced in ${chart.currency}, and only ${CURRENCY} is supported`);
137	  for (const holding of input.holdings) if (holding.currency && holding.currency !== CURRENCY && Number(holding.filled) > 0) return fail(`${holding.isin} is priced in ${holding.currency}, and only ${CURRENCY} is supported`);
138	
139	  const trades = rows.filter(row => row.kind !== "cash");
140	  const cryptoIsins = new Set(trades.filter(row => row.kind === "crypto").map(row => row.isin));
141	  const shares = new Map<string, bigint>(), prices = new Map<string, Prices>();
142	  for (const isin of new Set(trades.map(row => row.isin))) {
143	    shares.set(isin, 0n);
144	    prices.set(isin, pricesFrom(input.charts[isin], input.timeZone, tradePrices(trades.filter(row => row.isin === isin))));
145	  }
146	
147	  const byDay = new Map<string, HistoryRow[]>();
148	  for (const row of rows) {
149	    const day = calendarDate(row.at, input.timeZone);
150	    byDay.set(day, [...(byDay.get(day) ?? []), row]);
151	  }
152	  const eventDays = [...byDay.keys()].sort(), first = eventDays[0], lastEvent = eventDays.at(-1)!;
153	  const dayBefore = new Date(Date.parse(`${input.before}T00:00:00Z`) - 86400000).toISOString().slice(0, 10);
154	
155	  const days: HistoryDay[] = [];
156	  let cashMinor = 0n;
157	  for (const date of dayRange(first, lastEvent > dayBefore ? lastEvent : dayBefore)) {
158	    for (const row of byDay.get(date) ?? []) {
159	      const amount = BigInt(toMinor(row.amountText, CURRENCY));
160	      cashMinor += amount;
161	      if (row.kind === "cash") continue;
162	      const quantity = scaled(row.quantity!);
163	      shares.set(row.isin, shares.get(row.isin)! + (row.side === "BUY" ? quantity : -quantity));
164	    }
165	    for (const [isin, held] of shares) if (held < -TOLERANCE) return fail(`Shares of ${isin} go negative on ${date}`);
166	    if (date > dayBefore) continue;
167	
168	    let securitiesMinor = 0n, cryptoMinor = 0n;
169	    for (const [isin, held] of shares) {
170	      if (held <= TOLERANCE) continue;
171	      const price = priceOn(prices.get(isin)!, date);
172	      if (price === null) return fail(`${isin} has no price on ${date}`);
173	      if (cryptoIsins.has(isin)) cryptoMinor += value(held, price);
174	      else securitiesMinor += value(held, price);
175	    }
176	    days.push({ date, securitiesMinor, cryptoMinor, cashMinor, totalMinor: securitiesMinor + cryptoMinor + cashMinor });
177	  }
178	
179	  for (const isin of new Set([...shares.keys(), ...input.holdings.map(holding => holding.isin)])) {
180	    const held = input.holdings.find(holding => holding.isin === isin)?.filled ?? 0, replayed = shares.get(isin) ?? 0n;
181	    if (absolute(replayed - scaled(held)) > TOLERANCE) return fail(`Shares of ${isin} replay to ${decimalOf(replayed)}, but Scalable holds ${text(held)}`);
182	  }
183	  const balance = BigInt(toMinor(input.cashBalance, CURRENCY));
184	  if (absolute(cashMinor - balance) > CASH_TOLERANCE) return fail(`Cash replays to ${cashMinor} cents, but Scalable holds ${balance}`);
185	  return { ok: true, days: days.filter(day => day.date < input.before) };
186	}
187	
188	/** Each past day's value, or why it can't be trusted. The check runs over everything before any day is returned. */
189	export function calculateHistory(input: HistoryInput): HistoryResult {
190	  try { return replay(input); } catch (error) { return { ok: false, reason: error instanceof Error ? error.message : "The transactions could not be read" }; }
191	}
