8	// The run makes many calls in a row; the cron route allows it five minutes.
9	const LOGIN_NEEDED_MS = 600_000;
10	
11	/**
12	 * One try at a connection's calculated history. Separate from syncScalable, so it can't slow down or fail a sync.
13	 * A failed try saves nothing and leaves any earlier days in place; the reason stays on the connection, out of the owner's way.
14	 */
15	export async function rebuildScalableHistory(connection: { id: string; workspace_id: string; portfolio: unknown }, timeZone: string, today: string): Promise<"saved" | "failed" | "skipped"> {
16	  const db = serviceDb();
17	  const [events, items] = await Promise.all([loadWealthEvents(db, connection.workspace_id), loadWealthItems(db, connection.workspace_id, true)]);
18	  const before = firstSyncedOn(valuationHistory(events, items), scalableKnownIds([connection.portfolio as ScalableExtras | null]));
19	  // Nothing has synced yet, so there is no date to stop before. The next run tries again.
20	  if (!before) return "skipped";
21	  const failed = async (reason: string) => {
22	    const saved = await db.from("scalable_connections").update({ history_status: "failed", history_checked_on: today, history_error: reason.slice(0, 1000) }).eq("id", connection.id);
23	    if (saved.error) throw new Error(saved.error.message);
24	    return "failed" as const;
25	  };
26	  try {
27	    const result = calculateHistory(await withScalable(connection.id, connection.workspace_id, mcp => readHistoryInput(mcp, timeZone, before), fetch, LOGIN_NEEDED_MS));
28	    if (!result.ok) return await failed(result.reason);
29	    const saved = await db.rpc("replace_scalable_value_history", { p_connection_id: connection.id, p_checked_on: today,
30	      p_rows: result.days.map(day => ({ on_date: day.date, currency_code: "EUR", securities_minor: day.securitiesMinor.toString(), crypto_minor: day.cryptoMinor.toString(), cash_minor: day.cashMinor.toString(), total_minor: day.totalMinor.toString() })) });
31	    if (saved.error) throw new Error(saved.error.message);
32	    return "saved";
33	  } catch (error) {
34	    return failed(error instanceof Error ? error.message : "Scalable could not be read");
35	  }
36	}
