1	import { z } from "zod";
2	import type { SupabaseClient } from "@supabase/supabase-js";
3	
4	// Money lent to or borrowed from a person lives in Wealth as an ordinary asset ("Lent to Sam")
5	// or debt ("Owed to Sam"), so net worth, history and Undo work unchanged. The name carries the person.
6	export type IouDirection = "lent" | "borrowed";
7	const prefixes = { lent: "Lent to ", borrowed: "Owed to " } as const;
8	
9	export const iouCreateSchema = z.object({ direction: z.enum(["lent", "borrowed"]), person: z.string().trim().min(1).max(100),
10	  amountMinor: z.string().regex(/^[1-9]\d{0,17}$/), currencyCode: z.string().regex(/^[A-Z]{3}$/), date: z.iso.date() }).strict();
11	export const iouSettleSchema = z.object({ itemId: z.uuid(), transactionId: z.uuid(), appliedMinor: z.string().regex(/^[1-9]\d{0,17}$/) }).strict();
12	
13	export const iouName = (direction: IouDirection, person: string) => `${prefixes[direction]}${person.trim()}`.slice(0, 120);
14	export function parseIouName(name: string): { direction: IouDirection; person: string } | null {
15	  for (const direction of ["lent", "borrowed"] as const) if (name.startsWith(prefixes[direction]) && name.length > prefixes[direction].length) return { direction, person: name.slice(prefixes[direction].length) };
16	  return null;
17	}
18	
19	/** The wealth record a new IOU saves: a lent amount is an asset, a borrowed amount a zero-interest debt. */
20	export function iouRecord(input: z.infer<typeof iouCreateSchema>) {
21	  const lent = input.direction === "lent";
22	  return { kind: lent ? "asset" : "debt", name: iouName(input.direction, input.person), currency_code: input.currencyCode,
23	    amount_minor: `${lent ? "" : "-"}${input.amountMinor}`, as_of: input.date, quantity_text: null, unit_price_text: null, cost_basis_minor: null,
24	    linked_account_id: null, payment_account_id: null, annual_rate_text: lent ? null : "0", monthly_payment_minor: lent ? null : "0",
25	    next_payment_on: null, payment_assumption_id: null, payment_transaction_id: null };
26	}
27	
28	export type IouItem = { id: string; kind: string; name: string; currency_code: string; amount_minor: string; as_of: string; version: number; removed_at: string | null; linked_account_id: string | null };
29	export type IouTransaction = { id: string; description: string; amount_minor: string; currency_code: string; posted_on: string };
30	export type RepaymentMatch = { itemId: string; transactionId: string; appliedMinor: string; person: string; direction: IouDirection; owedMinor: string };
31	
32	const abs = (value: bigint) => value < 0n ? -value : value;
33	const normalize = (value: string) => value.normalize("NFD").replace(/\p{M}/gu, "").toLowerCase();
34	function mentions(description: string, person: string) {
35	  const name = normalize(person).trim().replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\s+/g, "\\s+");
36	  return new RegExp(`(^|[^\\p{L}\\p{N}])${name}($|[^\\p{L}\\p{N}])`, "u").test(normalize(description));
37	}
38	
39	export type LoanStart = { person: string; direction: IouDirection; amountMinor: bigint; currencyCode: string; date: string };
40	const dayGap = (a: string, b: string) => Math.abs(Date.parse(`${a}T00:00:00Z`) - Date.parse(`${b}T00:00:00Z`)) / 86_400_000;
41	
42	/**
43	 * The bank transaction that paid each IOU out (money lent leaves the account, money borrowed arrives): the exact amount
44	 * and currency, within 10 days of the IOU's date, naming the person (first name is enough). It is a loan, not spending,
45	 * so nothing should ask for its category or flag it as unusual.
46	 */
47	export function loanPayouts(loans: LoanStart[], transactions: IouTransaction[]) {
48	  const ids = new Set<string>();
49	  for (const loan of loans) {
50	    const signed = loan.direction === "lent" ? -loan.amountMinor : loan.amountMinor;
51	    const first = loan.person.trim().split(/\s+/)[0];
52	    const match = transactions.find(row => !ids.has(row.id) && row.currency_code === loan.currencyCode && BigInt(row.amount_minor) === signed
53	      && dayGap(row.posted_on, loan.date) <= 10 && (mentions(row.description, loan.person) || mentions(row.description, first)));
54	    if (match) ids.add(match.id);
55	  }
56	  return ids;
57	}
58	
59	/**
60	 * Bank transactions that look like a repayment: they name the person, move money the right way
61	 * (in for money lent, out for money borrowed), match the currency and come on or after the IOU's date.
62	 * Each transaction goes to the open IOU whose remaining amount is closest; partial payments count.
63	 */
64	export function repaymentMatches(items: IouItem[], transactions: IouTransaction[]): RepaymentMatch[] {
65	  const open = items.flatMap(item => {
66	    const parsed = parseIouName(item.name);
67	    const owed = BigInt(item.amount_minor);
68	    const right = parsed && ((parsed.direction === "lent" && item.kind === "asset" && owed > 0n) || (parsed.direction === "borrowed" && item.kind === "debt" && owed < 0n));
69	    return right && !item.removed_at && !item.linked_account_id ? [{ item, ...parsed, owed: abs(owed) }] : [];
70	  });
71	  const matches: RepaymentMatch[] = [];
72	  for (const transaction of transactions) {
73	    const amount = BigInt(transaction.amount_minor);
74	    const candidates = open.filter(entry => entry.item.currency_code === transaction.currency_code && transaction.posted_on >= entry.item.as_of
75	      && (entry.direction === "lent" ? amount > 0n : amount < 0n) && mentions(transaction.description, entry.person));
76	    if (!candidates.length) continue;
77	    const gap = (owed: bigint) => abs(owed - abs(amount));
78	    const best = candidates.reduce((a, b) => gap(b.owed) < gap(a.owed) ? b : a);
79	    matches.push({ itemId: best.item.id, transactionId: transaction.id, person: best.person, direction: best.direction,
80	      owedMinor: best.owed.toString(), appliedMinor: (abs(amount) < best.owed ? abs(amount) : best.owed).toString() });
81	  }
82	  return matches;
83	}
84	
85	/** The record after a repayment, or null when it settles the IOU in full (the item is then removed). */
86	export function settledRecord(item: IouItem & { annual_rate_text: string | null; monthly_payment_minor: string | null }, appliedMinor: string, today: string) {
87	  const lent = item.kind === "asset";
88	  const left = BigInt(item.amount_minor) + (lent ? -BigInt(appliedMinor) : BigInt(appliedMinor));
89	  if (lent ? left <= 0n : left >= 0n) return null;
90	  return { ...iouRecord({ direction: lent ? "lent" : "borrowed", person: parseIouName(item.name)!.person, amountMinor: abs(left).toString(), currencyCode: item.currency_code, date: today }),
91	    annual_rate_text: item.annual_rate_text, monthly_payment_minor: item.monthly_payment_minor };
92	}
93	
94	/**
95	 * Ids of the bank transactions that paid out a recorded IOU (e.g. the transfer that lent Bilal €1,000) or repaid one. Each IOU is read as
96	 * first recorded in Wealth, so a later repayment or a full settlement does not lose its payout.
97	 */
98	export async function loadLoanPayoutIds(supabase: SupabaseClient, workspaceId: string): Promise<Set<string>> {
99	  const events = await supabase.from("wealth_events").select("item_id, after").eq("workspace_id", workspaceId).is("undone_at", null).order("created_at").limit(2000);
100	  if (events.error) throw new Error(events.error.message);
101	  const loans = new Map<string, LoanStart>();
102	  for (const { item_id, after } of (events.data ?? []) as { item_id: string; after: { name?: string; amount_minor?: string | number; currency_code?: string; as_of?: string } }[]) {
103	    const parsed = parseIouName(String(after?.name ?? ""));
104	    if (loans.has(item_id) || !parsed || after.amount_minor === undefined || !after.currency_code || !after.as_of) continue;
105	    const amount = BigInt(after.amount_minor);
106	    loans.set(item_id, { ...parsed, amountMinor: amount < 0n ? -amount : amount, currencyCode: after.currency_code, date: String(after.as_of).slice(0, 10) });
107	  }
108	  // Accepted repayments are loan money too.
109	  const settled = await supabase.from("agent_proposals").select("payload").eq("workspace_id", workspaceId).eq("kind", "iou_settle").eq("status", "accepted").limit(1000);
110	  if (settled.error) throw new Error(settled.error.message);
111	  const repaid = (settled.data ?? []).map(row => row.payload?.transactionId).filter((id): id is string => typeof id === "string");
112	  if (!loans.size) return new Set(repaid);
113	  const amounts = [...new Set([...loans.values()].map(loan => (loan.direction === "lent" ? -loan.amountMinor : loan.amountMinor).toString()))];
114	  const rows = await supabase.from("transactions").select("id, description, amount_minor::text, currency_code, posted_on").eq("workspace_id", workspaceId).neq("status", "voided")
115	    .in("amount_minor", amounts.slice(0, 200)).limit(2000);
116	  if (rows.error) throw new Error(rows.error.message);
117	  return new Set([...loanPayouts([...loans.values()], rows.data ?? []), ...repaid]);
118	}
