1	// Candidates must come from earlier imports of the same account and currency.
2	// Pending and posted never merge: a stable external-ID match only counts when
3	// the stored status equals the incoming row status (missing status reads as
4	// posted for legacy rows). Any other fingerprint overlap goes to review so a
5	// pending hold and its later posted settlement cannot collapse or duplicate.
6	export function decideImportMatch(
7	  externalId: string | undefined,
8	  candidates: { id: string; externalId?: string; status?: string }[],
9	  rowStatus?: "posted" | "pending",
10	):
11	  | { action: "new" | "review" }
12	  | { action: "matched"; transactionId: string } {
13	  const normalizedRow = rowStatus ?? "posted";
14	  const stableMatches = externalId
15	    ? candidates.filter(candidate => candidate.externalId === externalId && (candidate.status ?? "posted") === normalizedRow)
16	    : [];
17	  if (stableMatches.length === 1) return { action: "matched", transactionId: stableMatches[0].id };
18	  if (!candidates.length) return { action: "new" };
19	  return { action: "review" };
20	}
