240	// Long enough for the sync on open to land, so a problem it fixes never flashes up.
241	const WAIT_MS = 15_000, SHOW_MS = 10_000, SEEN_KEY = "moneo-seen-notices";
242	
243	/** Which notices to show, and what to remember: a problem shows once, and again only if it went away and came back or changed. */
244	export function nextNotices(notices: HomeNotice[], seen: string[]) {
245	  const fresh = notices.filter(notice => !seen.includes(notice.text));
246	  return { fresh, seen: notices.map(notice => notice.text) };
247	}
248	
249	function readSeen(): string[] {
250	  try {
251	    const stored: unknown = JSON.parse(localStorage.getItem(SEEN_KEY) ?? "[]");
252	    return Array.isArray(stored) ? stored.filter(item => typeof item === "string") : [];
253	  } catch { return []; }
254	}
255	function writeSeen(seen: string[]) {
256	  try { localStorage.setItem(SEEN_KEY, JSON.stringify(seen)); } catch { /* blocked storage only means it may show again */ }
257	}
258	
259	/** Passing notices in the bottom-right corner, so the page itself stays clean. Details stay on Wealth and in Settings. */
260	export function HomeNotices({ notices }: { notices: HomeNotice[] }) {
261	  const [shown, setShown] = useState<HomeNotice[]>([]);
262	  const signature = JSON.stringify(notices);
263	  useEffect(() => {
264	    const current: HomeNotice[] = JSON.parse(signature);
265	    const texts = current.map(notice => notice.text);
266	    // Forget what has been fixed right away, so it can show again if it ever returns.
267	    writeSeen(readSeen().filter(text => texts.includes(text)));
268	    const wait = setTimeout(() => {
269	      const { fresh, seen } = nextNotices(current, readSeen());
270	      if (!fresh.length) return;
271	      writeSeen(seen);
272	      setShown(fresh);
273	    }, WAIT_MS);
274	    return () => clearTimeout(wait);
275	  }, [signature]);
276	  useEffect(() => {
277	    if (!shown.length) return;
278	    const hide = setTimeout(() => setShown([]), SHOW_MS);
279	    return () => clearTimeout(hide);
280	  }, [shown]);
281	  if (!shown.length) return null;
282	  return <div role="status" className="fixed bottom-[calc(5rem+env(safe-area-inset-bottom))] right-4 z-50 flex w-[calc(100%-2rem)] max-w-sm flex-col gap-2 lg:bottom-6 lg:right-6">
283	    {shown.map(notice => <div key={notice.text} className="flex items-start gap-1 rounded-xl border border-border bg-card py-1 pl-4 pr-1 text-sm shadow-lg">
