def sub(path, pairs):
    """Exact, unique replacements that keep the file's line endings."""
    s = open(path, encoding='utf-8', newline='').read()
    crlf = '\r\n' in s
    for a, b in pairs:
        a2 = a.replace('\n', '\r\n') if crlf else a
        b2 = b.replace('\n', '\r\n') if crlf else b
        if s.count(a2) != 1:
            raise SystemExit(f'{path}: {s.count(a2)} matches for {a[:90]!r}')
        s = s.replace(a2, b2)
    open(path, 'w', encoding='utf-8', newline='').write(s)


def write_like(path, text, crlf=True):
    open(path, 'w', encoding='utf-8', newline='').write(text.replace('\n', '\r\n') if crlf else text)

