-- The balance a bank states is its own observation, saved with the bank's date and balance type, even when
-- no new transaction arrives. balance_type is null for balances typed in or read from a statement row.
alter table public.balance_snapshots add column balance_type text check (balance_type is null or balance_type ~ '^[A-Z]{4}$');

create function public.record_bank_balance(p_connection_id uuid, p_account_name text, p_currency_code text, p_amount_minor bigint, p_as_of timestamptz, p_balance_type text) returns void
language plpgsql security definer set search_path='' as $$
declare connection public.bank_connections%rowtype; account uuid; zone text;
begin
  if p_connection_id is null or p_account_name is null or p_currency_code is null or p_amount_minor is null or p_as_of is null or p_balance_type is null then
    raise exception 'Invalid bank balance' using errcode = '22023'; end if;
  select * into connection from public.bank_connections where id = p_connection_id for update;
  if not found then raise exception 'Bank connection not found' using errcode = 'P0002'; end if;
  -- A bank sync imports into the account with the bank's name and currency; an empty account has no import to create it.
  select id into account from public.accounts where workspace_id = connection.workspace_id and name = p_account_name and currency_code = p_currency_code order by created_at limit 1;
  if account is null then
    insert into public.accounts(workspace_id, name, currency_code) values (connection.workspace_id, p_account_name, p_currency_code) returning id into account;
  end if;
  select timezone into zone from public.workspace_settings where workspace_id = connection.workspace_id;
  zone := coalesce(zone, 'Europe/Berlin');
  -- The same amount again on the same day says nothing new.
  if exists (select 1 from public.balance_snapshots where account_id = account and balance_type = p_balance_type and amount_minor = p_amount_minor and undone_at is null
    and (as_of at time zone zone)::date = (p_as_of at time zone zone)::date) then return; end if;
  insert into public.balance_snapshots(workspace_id, account_id, amount_minor, currency_code, as_of, provenance, boundary_kind, balance_type)
    values (connection.workspace_id, account, p_amount_minor, p_currency_code, p_as_of, 'bank:' || p_balance_type, 'date_only', p_balance_type);
end;
$$;
revoke all on function public.record_bank_balance(uuid, text, text, bigint, timestamptz, text) from public, anon, authenticated;
grant execute on function public.record_bank_balance(uuid, text, text, bigint, timestamptz, text) to service_role;

-- When a sync last tried, apart from when one last succeeded: a failed import never publishes last_synced_at,
-- but the background job must still wait before asking the bank again.
alter table public.bank_connections add column last_attempted_at timestamptz;
update public.bank_connections set last_attempted_at = last_synced_at;
grant select (last_attempted_at) on public.bank_connections to authenticated;

-- token_version moves whenever the sealed tokens change, so a request can tell its login was replaced before it
-- calls the login ended. The claim lets one request at a time spend the rotating refresh token.
-- portfolio_fetched_at is when the saved portfolio was read from Scalable, so an older read can't overwrite a newer one.
alter table public.scalable_connections
  add column token_version integer not null default 0,
  add column refresh_claimed_until timestamptz,
  add column portfolio_fetched_at timestamptz;

create function public.bump_scalable_token_version() returns trigger language plpgsql set search_path='' as $$
begin
  new.token_version := old.token_version + 1;
  new.refresh_claimed_until := null;
  return new;
end;
$$;
create trigger scalable_tokens_changed before update of tokens_encrypted on public.scalable_connections
  for each row when (old.tokens_encrypted is distinct from new.tokens_encrypted) execute function public.bump_scalable_token_version();

create function public.claim_scalable_refresh(p_connection_id uuid, p_token_version integer) returns boolean
language plpgsql security definer set search_path='' as $$
begin
  update public.scalable_connections set refresh_claimed_until = now() + interval '30 seconds'
    where id = p_connection_id and status = 'active' and token_version = p_token_version and (refresh_claimed_until is null or refresh_claimed_until < now());
  return found;
end;
$$;
revoke all on function public.claim_scalable_refresh(uuid, integer) from public, anon, authenticated;
grant execute on function public.claim_scalable_refresh(uuid, integer) to service_role;

-- As before, and: rejects a read older than the saved one (returning -1), and accepts a debt, which is how a
-- negative cash balance is kept (asset amounts can't go below zero). Nothing else about the sync changes.
drop function public.sync_scalable_wealth(uuid, jsonb, jsonb);
create function public.sync_scalable_wealth(p_connection_id uuid, p_items jsonb, p_portfolio jsonb, p_fetched_at timestamptz) returns integer
language plpgsql security definer set search_path='' as $$
declare connection public.scalable_connections%rowtype; owner uuid; entry jsonb; previous public.wealth_items%rowtype; item public.wealth_items%rowtype;
  existing boolean; kept uuid[] := '{}'; changed integer := 0;
begin
  if p_connection_id is null or p_fetched_at is null or jsonb_typeof(p_items) is distinct from 'array' or jsonb_typeof(p_portfolio) is distinct from 'object' then
    raise exception 'Invalid Scalable sync' using errcode = '22023'; end if;
  select * into connection from public.scalable_connections where id = p_connection_id and status = 'active' for update;
  if not found then raise exception 'Scalable connection is not active' using errcode = 'P0002'; end if;
  if connection.portfolio_fetched_at is not null and p_fetched_at < connection.portfolio_fetched_at then return -1; end if;
  select owner_id into owner from public.workspaces where id = connection.workspace_id;
  for entry in select value from jsonb_array_elements(p_items) loop
    if entry - array['id','kind','name','currency_code','amount_minor','quantity_text','unit_price_text','cost_basis_minor','as_of','annual_rate_text','monthly_payment_minor'] <> '{}'::jsonb
      or entry->>'kind' not in ('holding','asset','debt') then raise exception 'Unsupported Scalable wealth fields' using errcode = '22023'; end if;
    item := jsonb_populate_record(null::public.wealth_items, entry);
    if item.as_of > (now() at time zone coalesce((select timezone from public.workspace_settings where workspace_id = connection.workspace_id), 'Europe/Berlin'))::date then
      raise exception 'Valuation date cannot be in the future' using errcode = '22023'; end if;
    select * into previous from public.wealth_items where id = item.id for update;
    existing := found;
    if existing and previous.workspace_id <> connection.workspace_id then raise exception 'Wealth item belongs to another workspace' using errcode = '42501'; end if;
    if existing and (previous.kind <> item.kind or previous.currency_code <> item.currency_code) then raise exception 'Scalable position changed kind or currency' using errcode = '22023'; end if;
    kept := kept || item.id;
    if existing and previous.removed_at is null and previous.name = item.name and previous.amount_minor = item.amount_minor and previous.as_of = item.as_of
      and previous.quantity_text is not distinct from item.quantity_text and previous.unit_price_text is not distinct from item.unit_price_text
      and previous.cost_basis_minor is not distinct from item.cost_basis_minor then continue; end if;
    item.workspace_id := connection.workspace_id; item.version := coalesce(previous.version, 0) + 1; item.created_at := coalesce(previous.created_at, now());
    item.updated_at := now(); item.removed_at := null;
    insert into public.wealth_items select item.* on conflict (id) do update set name = excluded.name, amount_minor = excluded.amount_minor,
      quantity_text = excluded.quantity_text, unit_price_text = excluded.unit_price_text, cost_basis_minor = excluded.cost_basis_minor, as_of = excluded.as_of,
      version = excluded.version, removed_at = null, updated_at = excluded.updated_at;
    insert into public.wealth_events(workspace_id, item_id, actor_id, request_id, before, after)
      values (connection.workspace_id, item.id, owner, gen_random_uuid(), case when existing then public.wealth_record(previous) end, public.wealth_record(item));
    changed := changed + 1;
  end loop;
  -- Positions an earlier sync (from any connection of this workspace) wrote that Scalable no longer reports were sold.
  for previous in select w.* from public.wealth_items w where w.workspace_id = connection.workspace_id and w.removed_at is null and not (w.id = any(kept))
    and w.id in (select (jsonb_array_elements_text(c.portfolio->'itemIds'))::uuid from public.scalable_connections c where c.workspace_id = connection.workspace_id and c.portfolio ? 'itemIds')
    for update loop
    item := previous; item.removed_at := now(); item.version := previous.version + 1; item.updated_at := now();
    update public.wealth_items set removed_at = item.removed_at, version = item.version, updated_at = item.updated_at where id = item.id;
    insert into public.wealth_events(workspace_id, item_id, actor_id, request_id, before, after)
      values (connection.workspace_id, item.id, owner, gen_random_uuid(), public.wealth_record(previous), public.wealth_record(item));
    changed := changed + 1;
  end loop;
  update public.scalable_connections set portfolio = p_portfolio || jsonb_build_object('itemIds', to_jsonb(kept)), last_synced_at = now(), last_error = null, portfolio_fetched_at = p_fetched_at
    where id = p_connection_id;
  return changed;
end;
$$;
revoke all on function public.sync_scalable_wealth(uuid, jsonb, jsonb, timestamptz) from public, anon, authenticated;
grant execute on function public.sync_scalable_wealth(uuid, jsonb, jsonb, timestamptz) to service_role;

import type { SupabaseClient } from "@supabase/supabase-js";
import { calendarDate } from "./calendar";
import { formatMoney } from "./format";
import type { BalanceSnapshot, BalanceTransaction } from "./balances";

// The numbers checking each other. Worked out from the records whenever they are read, so one piece of evidence is
// one entry for as long as it's unresolved, and it goes away by itself once a correction fixes the records. Nothing here
// changes a number. Deliberately not findings: negative balances, differences from Scalable's returns, slow transfers.

export type Discrepancy = { key: string; kind: "bank_balance" | "broker_parts" | "history_boundary" | "import"; title: string; detail: string; href: string };

export const BOOKED_BALANCE_TYPES = new Set(["CLBD", "ITBD"]);
const BROKER_TOLERANCE_MINOR = 100n; // Rounding across positions can't reach a euro.
const abs = (value: bigint) => value < 0n ? -value : value;

/** Booked closing balances of one type must differ by exactly the accepted postings between them. */
export function bankBalanceFindings(accounts: { id: string; name: string; currency_code: string }[], snapshots: BalanceSnapshot[], ledger: BalanceTransaction[], timeZone: string, locale?: string): Discrepancy[] {
  const findings: Discrepancy[] = [];
  for (const account of accounts) {
    const closing = new Map<string, BalanceSnapshot>();
    for (const row of snapshots) {
      if (row.account_id !== account.id || row.undone_at || !row.balance_type || !BOOKED_BALANCE_TYPES.has(row.balance_type) || (row.boundary_kind ?? "date_only") !== "date_only") continue;
      // Only a balance at a clear point in the day compares: during a day, a date-only posting may fall on either side.
      if (calendarDate(new Date(Date.parse(row.as_of) - 1).toISOString(), timeZone) === calendarDate(row.as_of, timeZone)) continue;
      const key = `${row.balance_type}:${calendarDate(row.as_of, timeZone)}`, prior = closing.get(key);
      if (!prior || (row.created_at ?? "") > (prior.created_at ?? "")) closing.set(key, row);
    }
    const byType = new Map<string, BalanceSnapshot[]>();
    for (const row of closing.values()) byType.set(row.balance_type!, [...(byType.get(row.balance_type!) ?? []), row]);
    for (const rows of byType.values()) {
      rows.sort((a, b) => Date.parse(a.as_of) - Date.parse(b.as_of));
      for (let index = 1; index < rows.length; index++) {
        const before = rows[index - 1], after = rows[index];
        const from = calendarDate(before.as_of, timeZone), to = calendarDate(after.as_of, timeZone);
        const moved = ledger.reduce((sum, row) => {
          if (row.account_id !== account.id || row.status !== "posted" || row.currency_code !== after.currency_code) return sum;
          const day = row.posted_at ? calendarDate(row.posted_at, timeZone) : row.posted_on;
          return day > from && day <= to ? sum + BigInt(row.amount_minor) : sum;
        }, 0n);
        const expected = BigInt(before.amount_minor) + moved, stated = BigInt(after.amount_minor);
        if (expected === stated) continue;
        const money = (amount: bigint) => formatMoney(amount, after.currency_code, locale);
        findings.push({ key: `bank:${account.id}:${from}:${to}`, kind: "bank_balance", href: "/money/accounts",
          title: `${account.name} doesn't add up between ${from} and ${to}`,
          detail: `The bank said ${money(BigInt(before.amount_minor))} and then ${money(stated)}, but the postings between them make ${money(expected)}, ${money(abs(stated - expected))} ${stated > expected ? "less" : "more"} than it stated. A row still waiting in review, or one the bank never sent, can explain this.` });
      }
    }
  }
  return findings;
}

/** A broker's parts must add up to its own total. */
export function brokerFindings(portfolio: { currency: string; totalMinor: string; differenceMinor?: string; unsupported?: string[] } | null, locale?: string): Discrepancy[] {
  if (!portfolio) return [];
  const findings: Discrepancy[] = [];
  const difference = BigInt(portfolio.differenceMinor ?? "0");
  if (abs(difference) > BROKER_TOLERANCE_MINOR) findings.push({ key: "broker:parts", kind: "broker_parts", href: "/money/wealth#scalable-heading",
    title: "Scalable's parts don't add up to its total",
    detail: `Holdings, crypto and cash come to ${formatMoney(abs(difference), portfolio.currency, locale)} ${difference > 0n ? "less" : "more"} than Scalable's total of ${formatMoney(portfolio.totalMinor, portfolio.currency, locale)}. Net worth counts the parts.` });
  for (const item of portfolio.unsupported ?? []) findings.push({ key: `broker:unsupported:${item}`, kind: "broker_parts", href: "/money/wealth#scalable-heading", title: "Scalable reports something Moneo can't count", detail: item });
  return findings;
}

/** The last calculated day must roughly meet the first real value. A day's market move is allowed; a wrong replay isn't. */
export function historyBoundaryFindings(lastCalculated: { on_date: string; currency_code: string; total_minor: string } | null, firstReal: { date: string; minor: bigint } | null, movedOnBoundaryMinor = 0n, locale?: string): Discrepancy[] {
  if (!lastCalculated || !firstReal) return [];
  const expected = BigInt(lastCalculated.total_minor) + movedOnBoundaryMinor, gap = abs(firstReal.minor - expected);
  const allowed = abs(firstReal.minor) / 10n > 2000n ? abs(firstReal.minor) / 10n : 2000n; // 10%, or €20 on a small portfolio.
  if (gap <= allowed) return [];
  return [{ key: `history:${lastCalculated.on_date}`, kind: "history_boundary", href: "/money/wealth#scalable-heading", title: "Calculated Scalable history doesn't meet the first real value",
    detail: `The last calculated day, ${lastCalculated.on_date}, comes to ${formatMoney(expected, lastCalculated.currency_code, locale)}, and the first real value, ${firstReal.date}, is ${formatMoney(firstReal.minor, lastCalculated.currency_code, locale)}.` }];
}

/** A failed import stays listed until a later import of that account lands. */
export function importFindings(imports: { id: string; filename: string; status: string; created_at: string; mapping?: { accountName?: string | null } | null }[]): Discrepancy[] {
  return imports.filter(row => row.status === "failed" && !imports.some(other => other.status === "completed" && other.created_at > row.created_at && other.mapping?.accountName && other.mapping.accountName === row.mapping?.accountName))
    .map(row => ({ key: `import:${row.id}`, kind: "import", href: "/import", title: `${row.filename} didn't finish importing`, detail: "Its rows aren't in your numbers. The next sync retries a bank import; a file can be imported again." }));
}

/** Imports that didn't land, for the checks above. */
export async function loadImportStates(db: SupabaseClient, workspaceId: string) {
  const { data, error } = await db.from("imports").select("id, filename, status, created_at, mapping").eq("workspace_id", workspaceId).in("status", ["failed", "completed"]).order("created_at", { ascending: false }).limit(500);
  if (error) throw new Error(error.message);
  return data ?? [];
}

/** The sentence for Home's passing message: it changes only when the findings do, so it shows once per change. */
export function checksNotice(findings: { title: string }[]) {
  if (!findings.length) return null;
  return findings.length === 1 ? findings[0].title : `${findings.length} things in your numbers don't add up.`;
}

import { describe, expect, it } from "vitest";
import { bankBalanceFindings, brokerFindings, checksNotice, historyBoundaryFindings, importFindings } from "./net-worth-checks";
import { calendarDayBoundary } from "./calendar";

const timeZone = "Europe/Berlin";
const accounts = [{ id: "bank", name: "Bank", currency_code: "EUR" }];
const closing = (date: string, amount_minor: string, balance_type = "CLBD", created_at = `${date}T23:00:00Z`) => ({ account_id: "bank", amount_minor, currency_code: "EUR", as_of: calendarDayBoundary(date, timeZone), provenance: `bank:${balance_type}`, balance_type, created_at });
const posted = (posted_on: string, amount_minor: string) => ({ id: `${posted_on}:${amount_minor}`, account_id: "bank", amount_minor, currency_code: "EUR", posted_on, status: "posted" });

describe("bank balances adding up", () => {
  it("stays quiet when two closing balances differ by exactly the postings between them", () => {
    expect(bankBalanceFindings(accounts, [closing("2026-10-01", "10000"), closing("2026-10-05", "8000")], [posted("2026-10-01", "-999"), posted("2026-10-03", "-2000"), posted("2026-10-06", "-1")], timeZone)).toEqual([]);
  });

  it("raises one finding per pair of balances, with the same key on every read", () => {
    const run = () => bankBalanceFindings(accounts, [closing("2026-10-01", "10000"), closing("2026-10-05", "8000")], [posted("2026-10-03", "-1500")], timeZone);
    expect(run()).toHaveLength(1);
    expect(run()[0]).toMatchObject({ key: "bank:bank:2026-10-01:2026-10-05", kind: "bank_balance" });
    expect(run().map(item => item.key)).toEqual(run().map(item => item.key));
  });

  it("compares only booked balances of one type at a clear point in the day", () => {
    const during = { ...closing("2026-10-05", "1"), as_of: "2026-10-05T09:30:00Z" };
    const available = closing("2026-10-05", "1", "CLAV");
    const typed = { ...closing("2026-10-05", "1"), balance_type: null };
    const otherType = closing("2026-10-05", "1", "ITBD");
    expect(bankBalanceFindings(accounts, [closing("2026-10-01", "10000"), during, available, typed, otherType], [], timeZone)).toEqual([]);
  });

  it("does not raise a negative balance, or an undone observation", () => {
    expect(bankBalanceFindings(accounts, [closing("2026-10-01", "-500"), closing("2026-10-05", "-700"), { ...closing("2026-10-07", "1"), undone_at: "2026-10-08T00:00:00Z" }], [posted("2026-10-03", "-200")], timeZone)).toEqual([]);
  });
});

describe("the broker's parts", () => {
  const portfolio = { currency: "EUR", totalMinor: "10000" };
  it("allows rounding and reports a real gap and anything unsupported", () => {
    expect(brokerFindings({ ...portfolio, differenceMinor: "100" })).toEqual([]);
    expect(brokerFindings({ ...portfolio, differenceMinor: "101" })).toMatchObject([{ key: "broker:parts" }]);
    expect(brokerFindings({ ...portfolio, unsupported: ["A short position in Fund"] })).toMatchObject([{ key: "broker:unsupported:A short position in Fund" }]);
    expect(brokerFindings(null)).toEqual([]);
  });
});

describe("calculated history meeting reality", () => {
  const last = { on_date: "2026-11-06", currency_code: "EUR", total_minor: "100000" };
  it("allows a day's market move and counts money moved on the boundary day", () => {
    expect(historyBoundaryFindings(last, { date: "2026-11-07", minor: 105000n })).toEqual([]);
    expect(historyBoundaryFindings(last, { date: "2026-11-07", minor: 160000n }, 60000n)).toEqual([]);
    expect(historyBoundaryFindings(last, { date: "2026-11-07", minor: 160000n })).toMatchObject([{ key: "history:2026-11-06", kind: "history_boundary" }]);
    expect(historyBoundaryFindings(null, { date: "2026-11-07", minor: 1n })).toEqual([]);
  });
});

describe("imports landing", () => {
  const row = (id: string, status: string, created_at: string) => ({ id, filename: `${id}.csv`, status, created_at, mapping: { accountName: "Bank" } });
  it("lists a failed import until a later one of that account lands", () => {
    expect(importFindings([row("a", "failed", "2026-11-01")])).toMatchObject([{ key: "import:a" }]);
    expect(importFindings([row("a", "failed", "2026-11-01"), row("b", "completed", "2026-11-02")])).toEqual([]);
    expect(importFindings([row("b", "completed", "2026-10-31"), row("a", "failed", "2026-11-01")])).toHaveLength(1);
  });
});

it("words Home's message so it only changes with the findings", () => {
  expect(checksNotice([])).toBeNull();
  expect(checksNotice([{ title: "One thing" }])).toBe("One thing");
  expect(checksNotice([{ title: "a" }, { title: "b" }])).toBe("2 things in your numbers don't add up.");
});

